{% set active_page = 'monitors' %}
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>GoodWe Monitors - Upande Universal Dashboard</title>

  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Poppins:wght@400;500;600&display=swap" rel="stylesheet">
  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>

  <style>
    :root {
      --ink: #0a0a0a;
      --ink-1: #1a1a18;
      --ink-2: #2a2a26;
      --ink-3: #3a3a34;
      --ink-4: #5a5a52;
      --ink-mute: #8a8780;
      --ink-faint: #b8b6ae;

      --bg: #f4f3ef;
      --surface: #fafaf6;
      --surface-2: #ffffff;
      --hairline: rgba(10, 10, 10, 0.06);
      --shadow-card: 0 1px 0 rgba(10, 10, 10, 0.04), 0 8px 32px -16px rgba(10, 10, 10, 0.10);
      --shadow-hover: 0 1px 0 rgba(10, 10, 10, 0.06), 0 24px 48px -24px rgba(10, 10, 10, 0.18);

      --signal: #228883;
      --grad-ink: linear-gradient(135deg, #0a0a0a 0%, #3a3a34 100%);
      --grad-chart: linear-gradient(180deg, rgba(10, 10, 10, 0.18) 0%, rgba(10, 10, 10, 0) 100%);

      --sans: 'Poppins', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --display: 'Fraunces', Georgia, serif;
    }

    * { box-sizing: border-box; }
    body { margin: 0; font-family: var(--sans); font-size: 14px; color: var(--ink-3); background: var(--bg); line-height: 1.55; -webkit-font-smoothing: antialiased; }
    a { color: inherit; text-decoration: none; }

    /* Topbar Header */
    .topbar { background: var(--surface-2); padding: 14px 40px; display: flex; align-items: center; justify-content: space-between; position: sticky; top: 0; z-index: 10; border-bottom: 1px solid var(--hairline); }
    .topbar__brand { display: flex; align-items: center; gap: 16px; }
    .topbar__logo { height: 30px; width: auto; }
    .topbar__divider { width: 1px; height: 22px; background: var(--hairline); }
    .topbar__product { font: 600 14px var(--sans); color: var(--ink); letter-spacing: -.2px; }
    .topbar__product small { display: block; font: 500 10px var(--sans); text-transform: uppercase; letter-spacing: 1.6px; color: var(--ink-mute); margin-top: 1px; }
    .topbar__nav { display: flex; gap: 4px; margin-left: 32px; }
    .topbar__nav a { padding: 8px 14px; font: 500 13px var(--sans); color: var(--ink-4); border-radius: 999px; transition: all .2s; }
    .topbar__nav a:hover { background: rgba(10, 10, 10, 0.04); color: var(--ink); }
    .topbar__nav a.on { background: var(--ink); color: #fafaf6; }
    .topbar__right { display: flex; align-items: center; gap: 14px; font-size: 13px; color: var(--ink-4); margin-left: auto; }
    .avatar { width: 32px; height: 32px; border-radius: 50%; background: var(--grad-ink); color: #fafaf6; display: grid; place-items: center; font-weight: 600; font-size: 12px; }

    /* Page Layout */
    .page { max-width: 1480px; margin: 0 auto; padding: 48px 40px 80px; }
    .pagehead { display: grid; grid-template-columns: 1fr auto; align-items: end; gap: 32px; margin-bottom: 36px; }
    .pagehead__eyebrow { font: 500 11px var(--sans); text-transform: uppercase; letter-spacing: 2.2px; color: var(--ink-mute); margin-bottom: 10px; display: inline-flex; align-items: center; gap: 10px; }
    .pagehead__eyebrow::before { content: ""; width: 18px; height: 1px; background: var(--ink-3); }
    .pagehead__title { font: 600 44px/1.05 var(--sans); color: var(--ink); letter-spacing: -1.3px; margin: 0; }
    .pagehead__sub { margin-top: 8px; font-size: 15px; color: var(--ink-4); margin-bottom: 0; }
    .pagehead__tools { display: flex; gap: 10px; align-items: center; }

    .datepill { display: inline-flex; align-items: center; gap: 8px; background: var(--surface-2); border-radius: 999px; padding: 10px 16px; font: 500 12px var(--sans); color: var(--ink); box-shadow: var(--shadow-card); }
    .iconbtn { width: 40px; height: 40px; border: 0; background: var(--surface-2); border-radius: 50%; display: grid; place-items: center; cursor: pointer; color: var(--ink-4); box-shadow: var(--shadow-card); transition: all .2s; }
    .iconbtn:hover { color: var(--ink); transform: translateY(-1px); }

    /* Navigation Tabs */
    .tabs { display: inline-flex; gap: 4px; margin-bottom: 32px; background: rgba(10, 10, 10, 0.04); padding: 5px; border-radius: 999px; max-width: 100%; overflow-x: auto; }
    .tab { background: transparent; border: 0; font: 500 13px var(--sans); color: var(--ink-4); padding: 10px 18px; border-radius: 999px; cursor: pointer; display: inline-flex; align-items: center; gap: 8px; white-space: nowrap; transition: all .2s; text-decoration: none; }
    .tab:hover { color: var(--ink); }
    .tab.on { background: var(--grad-ink); color: #fafaf6; box-shadow: 0 4px 14px rgba(10, 10, 10, 0.20); }

    /* KPI Cards */
    .kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 18px; margin-bottom: 32px; }
    .kpi { background: var(--surface-2); border-radius: 20px; padding: 28px 30px; box-shadow: var(--shadow-card); transition: all .25s; position: relative; overflow: hidden; }
    .kpi:hover { transform: translateY(-3px); box-shadow: var(--shadow-hover); }
    .kpi__label { font: 500 11px var(--sans); text-transform: uppercase; letter-spacing: 1.8px; color: var(--ink-mute); margin-bottom: 14px; }
    .kpi__value { font: 600 44px/1 var(--sans); color: var(--ink); letter-spacing: -1.4px; font-feature-settings: "tnum"; display: inline-block; }
    .kpi__unit { font: 400 14px var(--sans); color: var(--ink-mute); margin-left: 4px; display: inline-block; }

    /* Card Containers */
    .card { background: var(--surface-2); border-radius: 24px; padding: 28px 32px; box-shadow: var(--shadow-card); margin-bottom: 18px; }
    .card__head { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 24px; gap: 24px; }
    .card__head h3 { margin: 0; font: 600 18px var(--sans); color: var(--ink); letter-spacing: -.4px; }
    .card__head .meta { font: 500 12px var(--sans); color: var(--ink-mute); }

    .row-2-eq { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-bottom: 18px; }
    .chart-container { position: relative; height: 260px; width: 100%; }
    .chart-container-full { position: relative; height: 300px; width: 100%; }

    @media (max-width: 1000px) { .row-2-eq { grid-template-columns: 1fr; } .pagehead { grid-template-columns: 1fr; } }
  </style>
</head>
<body>

  <!-- Top Navigation Bar -->
  <div class="topbar">
    <div class="topbar__brand">
      <img class="topbar__logo" alt="Upande" src="data:image/png;base64," />
      <div class="topbar__divider"></div>
      <div class="topbar__product">
        Upande GoodWe
        <small>Real-time Solar Monitoring</small>
      </div>
      <nav class="topbar__nav">
        <a href="monitors.html" class="on">Monitors</a>
        <a href="inverters.html">Inverters</a>
      </nav>
    </div>
    <div class="topbar__right">
      <span>system@upande.com</span>
      <div class="avatar">GW</div>
    </div>
  </div>

  <div class="page">
    <div class="pagehead">
      <div>
        <div class="pagehead__eyebrow">Upande GoodWe Integration</div>
        <h1 class="pagehead__title">GoodWe Monitors</h1>
        <p class="pagehead__sub">Real-time system metric aggregations & multi-inverter averages</p>
      </div>
      <div class="pagehead__tools">
        <span class="datepill" id="last-sync">Loading...</span>
        <button class="iconbtn" id="refresh-btn" title="Refresh Data">↻</button>
      </div>
    </div>

    <!-- Navigation Pills/Tabs -->
    <div class="tabs">
      <a href="monitors.html" class="tab on">
        <svg viewBox="0 0 24 24"><path d="M18 20V10M12 20V4M6 20v-6"></path></svg> Overview & Averages
      </a>
      <a href="inverters.html" class="tab">
        <svg viewBox="0 0 24 24"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"></rect><line x1="8" y1="21" x2="16" y2="21"></line><line x1="12" y1="17" x2="12" y2="21"></line></svg> Inverter Fleet
      </a>
    </div>

    <!-- KPI Cards -->
    <div class="kpi-grid">
      <div class="kpi">
        <div class="kpi__label">Average Power</div>
        <div class="kpi__value" id="avg-power">—</div>
        <div class="kpi__unit">kW</div>
      </div>
      <div class="kpi">
        <div class="kpi__label">Peak Power</div>
        <div class="kpi__value" id="peak-power">—</div>
        <div class="kpi__unit">kW</div>
      </div>
      <div class="kpi">
        <div class="kpi__label">Avg Daily Energy</div>
        <div class="kpi__value" id="daily-energy">—</div>
        <div class="kpi__unit">kWh</div>
      </div>
      <div class="kpi">
        <div class="kpi__label">Avg Total Energy</div>
        <div class="kpi__value" id="total-energy">—</div>
        <div class="kpi__unit">kWh</div>
      </div>
    </div>

    <!-- Analytics Section -->
    <div class="card">
      <div class="card__head">
        <h3>Power Output & Load Trend</h3>
        <span class="meta">Averaged across active inverters</span>
      </div>
      <div class="chart-container-full">
        <canvas id="chart-power-output"></canvas>
      </div>
    </div>

    <div class="row-2-eq">
      <div class="card">
        <div class="card__head">
          <h3>Daily Energy Output</h3>
          <span class="meta">kWh / Interval</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-daily-energy"></canvas>
        </div>
      </div>

      <div class="card">
        <div class="card__head">
          <h3>Average Battery SOC</h3>
          <span class="meta">Fleet State of Charge</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-battery-soc"></canvas>
        </div>
      </div>
    </div>

    <div class="row-2-eq">
      <div class="card">
        <div class="card__head">
          <h3>Battery Power Trend</h3>
          <span class="meta">Avg Charge/Discharge (kW)</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-battery-power"></canvas>
        </div>
      </div>

      <div class="card">
        <div class="card__head">
          <h3>Grid Power Exchange</h3>
          <span class="meta">Avg Import/Export (kW)</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-grid-power"></canvas>
        </div>
      </div>
    </div>

  </div>

  <script>
  document.addEventListener("DOMContentLoaded", function () {
    const REFRESH_INTERVAL = 60000;
    const chartInstances = {};

    function format(value, decimals = 1) {
      if (value === null || value === undefined || value === "") return "—";
      return Number(value).toLocaleString(undefined, {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals
      });
    }

    function createOrUpdateChart(chartId, config) {
      if (chartInstances[chartId]) {
        chartInstances[chartId].destroy();
      }
      const canvas = document.getElementById(chartId);
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      chartInstances[chartId] = new Chart(ctx, config);
    }

    async function loadDashboard() {
      try {
        let readings = [];
        if (typeof frappe !== 'undefined') {
          const response = await frappe.call({
            method: "frappe.client.get_list",
            args: {
              doctype: "GoodWe Reading",
              fields: [
                "name", "inverter", "reading_time", "current_power_kw",
                "daily_energy_kwh", "total_energy_kwh", "grid_power_kw",
                "load_power_kw", "battery_soc", "battery_power_kw", "status", "sync_time"
              ],
              order_by: "reading_time desc",
              limit_page_length: 1000
            }
          });
          readings = response.message || [];
        } else {
          // Fallback mock data for development preview
          readings = [
            { inverter: "INV-01", reading_time: "2026-09-08 12:00", current_power_kw: 12.4, daily_energy_kwh: 45.2, total_energy_kwh: 1200, grid_power_kw: 1.2, load_power_kw: 10.1, battery_soc: 85, battery_power_kw: 2.1, sync_time: "2026-09-08 12:00" },
            { inverter: "INV-02", reading_time: "2026-09-08 12:00", current_power_kw: 14.1, daily_energy_kwh: 48.6, total_energy_kwh: 1350, grid_power_kw: 0.8, load_power_kw: 11.5, battery_soc: 88, battery_power_kw: 2.3, sync_time: "2026-09-08 12:00" },
            { inverter: "INV-01", reading_time: "2026-09-08 11:45", current_power_kw: 10.2, daily_energy_kwh: 41.0, total_energy_kwh: 1195, grid_power_kw: 2.1, load_power_kw: 9.8, battery_soc: 82, battery_power_kw: 1.8, sync_time: "2026-09-08 11:45" },
            { inverter: "INV-02", reading_time: "2026-09-08 11:45", current_power_kw: 11.8, daily_energy_kwh: 43.1, total_energy_kwh: 1342, grid_power_kw: 1.5, load_power_kw: 10.2, battery_soc: 84, battery_power_kw: 1.9, sync_time: "2026-09-08 11:45" }
          ];
        }

        if (!readings.length) return;

        const latestPerInverter = {};
        readings.forEach(r => {
          if (!latestPerInverter[r.inverter]) latestPerInverter[r.inverter] = r;
        });
        const latestDevices = Object.values(latestPerInverter);

        const avgPower = latestDevices.reduce((sum, r) => sum + (Number(r.current_power_kw) || 0), 0) / latestDevices.length;
        const peakPower = Math.max(...latestDevices.map(r => Number(r.current_power_kw) || 0));
        const dailyEnergy = latestDevices.reduce((sum, r) => sum + (Number(r.daily_energy_kwh) || 0), 0) / latestDevices.length;
        const totalEnergy = latestDevices.reduce((sum, r) => sum + (Number(r.total_energy_kwh) || 0), 0) / latestDevices.length;

        document.getElementById("avg-power").textContent = format(avgPower);
        document.getElementById("peak-power").textContent = format(peakPower);
        document.getElementById("daily-energy").textContent = format(dailyEnergy);
        document.getElementById("total-energy").textContent = format(totalEnergy);

        const latestSync = latestDevices.map(r => r.sync_time).filter(Boolean).sort().reverse()[0];
        document.getElementById("last-sync").textContent = latestSync ? "Sync " + latestSync.split(" ")[1]?.substring(0, 5) : "No sync";

        const groupedByTime = {};
        readings.forEach(r => {
          const timeKey = r.reading_time || r.sync_time;
          if (!timeKey) return;

          if (!groupedByTime[timeKey]) {
            groupedByTime[timeKey] = { count: 0, current_power_kw: 0, load_power_kw: 0, daily_energy_kwh: 0, battery_soc: 0, battery_power_kw: 0, grid_power_kw: 0 };
          }

          groupedByTime[timeKey].count += 1;
          groupedByTime[timeKey].current_power_kw += Number(r.current_power_kw) || 0;
          groupedByTime[timeKey].load_power_kw += Number(r.load_power_kw) || 0;
          groupedByTime[timeKey].daily_energy_kwh += Number(r.daily_energy_kwh) || 0;
          groupedByTime[timeKey].battery_soc += Number(r.battery_soc) || 0;
          groupedByTime[timeKey].battery_power_kw += Number(r.battery_power_kw) || 0;
          groupedByTime[timeKey].grid_power_kw += Number(r.grid_power_kw) || 0;
        });

        const timeKeysSorted = Object.keys(groupedByTime).sort().slice(-20);
        const averagedSeries = timeKeysSorted.map(t => {
          const item = groupedByTime[t];
          const cnt = item.count || 1;
          return {
            time: t.split(" ")[1]?.substring(0, 5) || t,
            current_power_kw: item.current_power_kw / cnt,
            load_power_kw: item.load_power_kw / cnt,
            daily_energy_kwh: item.daily_energy_kwh / cnt,
            battery_soc: item.battery_soc / cnt,
            battery_power_kw: item.battery_power_kw / cnt,
            grid_power_kw: item.grid_power_kw / cnt
          };
        });

        const timeLabels = averagedSeries.map(s => s.time);

        createOrUpdateChart("chart-power-output", {
          type: 'line',
          data: {
            labels: timeLabels,
            datasets: [
              { label: 'Avg Solar Output (kW)', data: averagedSeries.map(s => s.current_power_kw), borderColor: '#228883', backgroundColor: 'rgba(34, 136, 131, 0.12)', fill: true, tension: 0.35, borderWidth: 2 },
              { label: 'Avg Load Power (kW)', data: averagedSeries.map(s => s.load_power_kw), borderColor: '#0a0a0a', backgroundColor: 'rgba(10, 10, 10, 0.05)', fill: true, tension: 0.35, borderWidth: 2 }
            ]
          },
          options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom' } }, scales: { x: { grid: { display: false } }, y: { beginAtZero: true } } }
        });

        createOrUpdateChart("chart-daily-energy", {
          type: 'bar',
          data: {
            labels: timeLabels,
            datasets: [{ label: 'Avg Daily Energy (kWh)', data: averagedSeries.map(s => s.daily_energy_kwh), backgroundColor: '#0a0a0a', borderRadius: 6 }]
          },
          options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { x: { grid: { display: false } }, y: { beginAtZero: true } } }
        });

        const avgLatestSOC = Math.round(latestDevices.reduce((sum, r) => sum + (Number(r.battery_soc) || 0), 0) / (latestDevices.length || 1));
        createOrUpdateChart("chart-battery-soc", {
          type: 'doughnut',
          data: {
            labels: ['Avg SOC', 'Remaining'],
            datasets: [{ data: [avgLatestSOC, Math.max(0, 100 - avgLatestSOC)], backgroundColor: ['#228883', 'rgba(10,10,10,0.06)'], borderWidth: 0 }]
          },
          options: { responsive: true, maintainAspectRatio: false, cutout: '75%', plugins: { legend: { display: false } } },
          plugins: [{
            id: 'textInside',
            afterDraw: function(chart) {
              const width = chart.width, height = chart.height, ctx = chart.ctx;
              ctx.restore();
              ctx.font = "600 28px Poppins, sans-serif";
              ctx.textBaseline = "middle";
              ctx.fillStyle = "#0a0a0a";
              const text = avgLatestSOC + "%", textX = Math.round((width - ctx.measureText(text).width) / 2), textY = height / 2;
              ctx.fillText(text, textX, textY);
              ctx.save();
            }
          }]
        });

        createOrUpdateChart("chart-battery-power", {
          type: 'line',
          data: {
            labels: timeLabels,
            datasets: [{ label: 'Avg Battery Power (kW)', data: averagedSeries.map(s => s.battery_power_kw), borderColor: '#5a5a52', backgroundColor: 'rgba(90, 90, 82, 0.1)', fill: true, tension: 0.3, borderWidth: 2 }]
          },
          options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { x: { grid: { display: false } }, y: { beginAtZero: true } } }
        });

        createOrUpdateChart("chart-grid-power", {
          type: 'bar',
          data: {
            labels: timeLabels,
            datasets: [{ label: 'Avg Grid Power (kW)', data: averagedSeries.map(s => s.grid_power_kw), backgroundColor: '#228883', borderRadius: 6 }]
          },
          options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { x: { grid: { display: false } }, y: { beginAtZero: true } } }
        });

      } catch (error) {
        console.error("GoodWe Monitors error:", error);
      }
    }

    document.getElementById("refresh-btn").addEventListener("click", loadDashboard);
    loadDashboard();
    setInterval(loadDashboard, REFRESH_INTERVAL);
  });
  </script>
</body>
</html>

javascript:
frappe.ready(function () {
  /* ------------------------------------------------------------------
   * Configuration
   * ------------------------------------------------------------------ */
  const SOLAR_REFRESH_MS = 60 * 1000;        // GoodWe readings
  const WATER_REFRESH_MS = 10 * 60 * 1000;   // manual logs change rarely
  const API = "upande_goodwe.goodwe.ro_dashboard";
  const LOG_DOCTYPE = "RO Daily Log";
  const LOG_FIELDS = [
    "name", "site", "log_date", "borehole_meter", "smart_meter",
    "permeate_m3", "reject_m3", "units_sold", "rw_tank_level", "tw_tank_level", "notes",
    "modified", "modified_by"
  ];
  const FIELD_LABELS = {
    borehole_meter: "Borehole meter", smart_meter: "Smart meter", permeate_m3: "Permeate",
    reject_m3: "Reject", units_sold: "Units sold", rw_tank_level: "Raw tank %", tw_tank_level: "Treated tank %", notes: "Notes"
  };

  // Sites without an RO plant are measured borehole -> sales only.
  const SITE_CONFIG = {
    VV: { hasRO: true, hasSmartMeter: true },
    Yamin: { hasRO: false, hasSmartMeter: false }
  };

  // Defaults taken from the RO efficiency workbook:
  //  - recovery design value 64.5% (B = C / 35.5 * 64.5)
  //  - Ubuntu smart meter reads ~8.2% above the mechanical borehole meter (median, 2026)
  const DEFAULT_SETTINGS = {
    tariff: 0,
    recoveryTarget: 64.5,
    devExpected: 8.2,
    devTolerance: 3,
    nrwWarn: 25,
    nrwCritical: 40
  };

  // Share of daily estate flow per hour (%), "Distribution during day" sheet, 17–23 Aug 2026.
  const BASELINE_DEMAND = [
    1.50, 1.08, 1.12, 0.75, 0.67, 1.10, 2.05, 3.37, 6.12, 7.26, 7.81, 8.19,
    8.31, 5.67, 4.90, 4.02, 4.06, 5.02, 5.43, 5.31, 5.89, 4.68, 3.78, 1.93
  ];

  const C = {
    ink: "#0a0a0a", mute: "#8a8780", faint: "rgba(10,10,10,0.12)",
    water: "#2b6f9e", waterSoft: "rgba(43,111,158,0.14)",
    solar: "#7aa23f", solarSoft: "rgba(122,162,63,0.14)",
    warn: "#d9962e", crit: "#c4302b", signal: "#228883", load: "#b08d55"
  };

  const state = {
    site: storageGet("ro_dash_site") || "VV",
    settings: Object.assign({}, DEFAULT_SETTINGS, storageGetJSON("ro_dash_settings") || {}),
    logs: [],
    logsError: null,
    energyFromApi: null,
    solarProfileFromApi: null,
    readings: [],
    solarLatest: null,
    rows: [],
    missingDays: [],
    editingName: null,
    editingDoc: null,
    showAllRows: false,
    highlightName: null,
    range: null,
    solarTruncated: false
  };
  state.range = initialRange();
  if (!SITE_CONFIG[state.site]) state.site = "VV";
  const charts = {};

  /* ------------------------------------------------------------------
   * Small helpers
   * ------------------------------------------------------------------ */
  function storageGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
  function storageSet(k, v) { try { localStorage.setItem(k, v); } catch (e) { /* private mode */ } }
  function storageGetJSON(k) { try { return JSON.parse(storageGet(k)); } catch (e) { return null; } }

  function num(v) {
    if (v === null || v === undefined || v === "") return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  }
  function format(value, decimals = 1) {
    if (value === null || value === undefined || value === "" || !Number.isFinite(Number(value))) return "—";
    return Number(value).toLocaleString(undefined, { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
  }
  function escapeHtml(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, ch => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]));
  }
  function pad(n) { return String(n).padStart(2, "0"); }
  function todayStr() { const d = new Date(); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; }
  function toUTC(s) { const [y, m, d] = String(s).slice(0, 10).split("-").map(Number); return Date.UTC(y, m - 1, d); }
  function addDays(s, n) { const d = new Date(toUTC(s) + n * 86400000); return d.toISOString().slice(0, 10); }
  function dayDiff(a, b) { return Math.round((toUTC(b) - toUTC(a)) / 86400000); }
  function weekday(s) { return new Date(toUTC(s)).getUTCDay(); }
  const WEEKDAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  function fmtDate(s, long) {
    return new Date(toUTC(s)).toLocaleDateString("en-GB", long
      ? { weekday: "short", day: "numeric", month: "short", year: "numeric", timeZone: "UTC" }
      : { day: "numeric", month: "short", timeZone: "UTC" });
  }
  function mean(a) { const v = a.filter(x => x != null); return v.length ? v.reduce((s, x) => s + x, 0) / v.length : null; }
  function sum(a) { return a.filter(x => x != null).reduce((s, x) => s + x, 0); }
  function stdev(a) {
    const v = a.filter(x => x != null); if (v.length < 2) return null;
    const m = mean(v); return Math.sqrt(v.reduce((s, x) => s + (x - m) ** 2, 0) / (v.length - 1));
  }
  function rolling(values, n) {
    return values.map((_, i) => mean(values.slice(Math.max(0, i - n + 1), i + 1)));
  }
  function lastWith(rows, key) { for (let i = rows.length - 1; i >= 0; i--) if (rows[i][key] != null) return rows[i]; return null; }
  function valuesOf(rows, key) { return rows.map(r => r[key]).filter(v => v != null); }
  function prettyDate(dt) {
    try { if (frappe.datetime && frappe.datetime.prettyDate) return frappe.datetime.prettyDate(dt); } catch (e) { /* ignore */ }
    return dt;
  }

  /* Period filter helpers */
  const SOLAR_READING_LIMIT = 5000;
  function presetRange(preset, anchor) {
    const t = todayStr();
    switch (preset) {
      case "today": return { preset, from: t, to: t };
      case "yesterday": { const y = addDays(t, -1); return { preset, from: y, to: y }; }
      case "day": { const d = anchor || addDays(t, -1); return { preset, from: d, to: d }; }
      case "7d": return { preset, from: addDays(t, -6), to: t };
      case "90d": return { preset, from: addDays(t, -89), to: t };
      case "mtd": return { preset, from: t.slice(0, 7) + "-01", to: t };
      case "lastmonth": {
        const end = addDays(t.slice(0, 7) + "-01", -1);
        return { preset, from: end.slice(0, 7) + "-01", to: end };
      }
      case "30d":
      default: return { preset: "30d", from: addDays(t, -29), to: t };
    }
  }
  function rangeDays(r) { return dayDiff(r.from, r.to) + 1; }
  function isLive() { return state.range.to >= addDays(todayStr(), -1); }
  function isSingleDay() { return state.range.from === state.range.to; }
  function inRange(rows) { return rows.filter(r => r.date >= state.range.from && r.date <= state.range.to); }
  function upToEnd(rows) { return rows.filter(r => r.date <= state.range.to); }
  function validDate(v) { return /^\d{4}-\d{2}-\d{2}$/.test(v || "") && !isNaN(toUTC(v)); }
  function initialRange() {
    try {
      const q = new URLSearchParams(window.location.search);
      let from = q.get("from"), to = q.get("to");
      if (validDate(from) && validDate(to)) {
        if (from > to) [from, to] = [to, from];
        if (to > todayStr()) to = todayStr();
        return { preset: from === to ? "day" : "custom", from, to };
      }
    } catch (e) { /* ignore */ }
    return presetRange(storageGet("ro_dash_preset") || "30d");
  }
  function rangeText(r) {
    if (r.from === r.to) return fmtDate(r.from, true);
    const sameYear = r.from.slice(0, 4) === r.to.slice(0, 4);
    const a = new Date(toUTC(r.from)).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: sameYear ? undefined : "numeric", timeZone: "UTC" });
    return `${a} – ${fmtDate(r.to, true).replace(/^\w+, /, "")}`;
  }

  function toast(msg) {
    const el = document.getElementById("toast");
    el.textContent = msg; el.classList.add("show");
    clearTimeout(toast._t); toast._t = setTimeout(() => el.classList.remove("show"), 2800);
  }

  // Calls a whitelisted method without Frappe's error dialogs, so missing
  // optional endpoints can fall back silently.
  async function api(method, args) {
    const res = await fetch(`/api/method/${method}`, {
      method: "POST",
      credentials: "same-origin",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "X-Frappe-CSRF-Token": (window.frappe && frappe.csrf_token) || ""
      },
      body: JSON.stringify(args || {})
    });
    let body = {};
    try { body = await res.json(); } catch (e) { /* non-JSON */ }
    if (!res.ok || body.exc_type) {
      const err = new Error(serverMessage(body) || `${res.status} ${res.statusText}`);
      err.status = res.status;
      throw err;
    }
    return body.message;
  }
  function serverMessage(body) {
    try {
      if (body._server_messages) {
        return JSON.parse(body._server_messages)
          .map(m => { try { return JSON.parse(m).message; } catch (e) { return m; } })
          .join(" ").replace(/<[^>]+>/g, "");
      }
      if (body.exception) return String(body.exception).split(":").slice(1).join(":").trim();
    } catch (e) { /* ignore */ }
    return "";
  }

  function upsertChart(id, config) {
    const existing = charts[id];
    if (existing && existing.config.type === config.type) {
      existing.data = config.data;
      existing.options = config.options;
      existing.update("none");
      return;
    }
    if (existing) existing.destroy();
    const canvas = document.getElementById(id);
    if (!canvas) return;
    charts[id] = new Chart(canvas.getContext("2d"), config);
  }
  function setEmpty(id, isEmpty) {
    const el = document.getElementById(`empty-${id}`);
    if (el) el.classList.toggle("show", !!isEmpty);
  }
  const baseOptions = () => ({
    responsive: true,
    maintainAspectRatio: false,
    interaction: { mode: "index", intersect: false },
    plugins: { legend: { position: "bottom", labels: { boxWidth: 12, usePointStyle: true } } },
    scales: { x: { grid: { display: false } }, y: { beginAtZero: true, grid: { color: "rgba(10,10,10,0.05)" } } }
  });

  /* ------------------------------------------------------------------
   * Solar (GoodWe API) — existing dashboard, kept and hardened
   * ------------------------------------------------------------------ */
  async function loadSolar() {
    let readings = [];
    try {
      readings = await api("frappe.client.get_list", {
        doctype: "GoodWe Reading",
        fields: ["name", "inverter", "reading_time", "current_power_kw", "daily_energy_kwh", "total_energy_kwh",
          "grid_power_kw", "load_power_kw", "battery_soc", "battery_power_kw", "status", "sync_time"],
        filters: [["reading_time", "between", [`${state.range.from} 00:00:00`, `${state.range.to} 23:59:59`]]],
        order_by: "reading_time desc",
        limit_page_length: SOLAR_READING_LIMIT
      }) || [];
      state.solarError = null;
    } catch (error) {
      console.error("GoodWe readings error:", error);
      state.solarError = "Solar data unavailable";
      readings = [];
    }
    state.readings = readings;
    state.solarTruncated = readings.length >= SOLAR_READING_LIMIT;
  }

  // Picks a bucket size so long periods stay readable.
  function solarBucket(t, spanDays) {
    if (spanDays <= 1) return t.slice(0, 16);           // each reading (minute)
    if (spanDays <= 7) return t.slice(0, 13) + ":00";   // hourly
    return t.slice(0, 10);                               // daily
  }
  function bucketLabel(key, spanDays) {
    if (spanDays <= 1) return key.slice(11, 16);
    if (spanDays <= 7) return `${fmtDate(key.slice(0, 10))} ${key.slice(11, 16)}`;
    return fmtDate(key.slice(0, 10));
  }

  function renderSolar() {
    const readings = state.readings;
    const live = isLive();
    const days = rangeDays(state.range);
    document.getElementById("solar-asof").textContent =
      (live && days === 1 ? "Live from GoodWe" : `GoodWe readings for ${rangeText(state.range)}`) +
      (state.solarTruncated ? `, latest ${SOLAR_READING_LIMIT.toLocaleString()} readings only` : "");
    if (!readings.length) {
      document.getElementById("last-sync").textContent = state.solarError || (live ? "No solar readings yet" : "No solar readings in this period");
      ["avg-power", "peak-power", "daily-energy", "total-energy"].forEach(id => { document.getElementById(id).textContent = "—"; });
      ["chart-power-output", "chart-battery-power", "chart-grid-power", "chart-battery-soc"].forEach(id => {
        if (charts[id]) { charts[id].destroy(); delete charts[id]; }
      });
      drawDailyEnergy([], []); // official daily totals can exist for days without readings
      state.solarLatest = null;
      document.getElementById("power-meta").textContent = "No readings in this period";
      return;
    }

    const latestPerInverter = {};
    readings.forEach(r => { if (!latestPerInverter[r.inverter]) latestPerInverter[r.inverter] = r; });
    const latest = Object.values(latestPerInverter);
    const n = latest.length || 1;

    const avgPower = latest.reduce((s, r) => s + (Number(r.current_power_kw) || 0), 0) / n;
    const peakPower = Math.max(...latest.map(r => Number(r.current_power_kw) || 0));
    const dailyEnergy = latest.reduce((s, r) => s + (Number(r.daily_energy_kwh) || 0), 0) / n;
    const totalEnergy = latest.reduce((s, r) => s + (Number(r.total_energy_kwh) || 0), 0) / n;
    const avgSOC = Math.round(latest.reduce((s, r) => s + (Number(r.battery_soc) || 0), 0) / n);
    state.solarLatest = { avgPower, peakPower, dailyEnergy, totalEnergy, avgSOC, inverters: latest.length };

    document.getElementById("avg-power").textContent = format(avgPower);
    document.getElementById("peak-power").textContent = format(peakPower);
    document.getElementById("daily-energy").textContent = format(dailyEnergy);
    document.getElementById("total-energy").textContent = format(totalEnergy);

    const latestSync = latest.map(r => r.sync_time).filter(Boolean).sort().reverse()[0];
    document.getElementById("last-sync").textContent = !live ? `Viewing ${rangeText(state.range)}`
      : latestSync ? "Solar updated " + prettyDate(latestSync) : "No sync time";

    // Average across inverters, bucketed by minute / hour / day depending on the span
    const times = readings.map(r => r.reading_time).filter(Boolean).sort();
    const spanDays = times.length ? dayDiff(times[0].slice(0, 10), times[times.length - 1].slice(0, 10)) + 1 : 1;
    const grouped = {};
    readings.forEach(r => {
      const t = r.reading_time || r.sync_time; if (!t) return;
      const key = solarBucket(t, spanDays);
      const g = grouped[key] || (grouped[key] = { count: 0, current_power_kw: 0, load_power_kw: 0, daily_energy_kwh: 0, battery_power_kw: 0, grid_power_kw: 0 });
      g.count += 1;
      ["current_power_kw", "load_power_kw", "daily_energy_kwh", "battery_power_kw", "grid_power_kw"].forEach(k => { g[k] += Number(r[k]) || 0; });
    });
    let keys = Object.keys(grouped).sort();
    if (spanDays <= 1 && keys.length > 160) { const step = Math.ceil(keys.length / 160); keys = keys.filter((_, i) => i % step === 0); }
    const series = keys.map(t => {
      const g = grouped[t], c = g.count || 1;
      return {
        time: bucketLabel(t, spanDays),
        current_power_kw: g.current_power_kw / c, load_power_kw: g.load_power_kw / c,
        daily_energy_kwh: g.daily_energy_kwh / c, battery_power_kw: g.battery_power_kw / c, grid_power_kw: g.grid_power_kw / c
      };
    });
    const labels = series.map(s => s.time);
    document.getElementById("power-meta").textContent = spanDays <= 1 ? "Averaged across inverters, through the day"
      : spanDays <= 7 ? "Hourly average across inverters" : "Daily average across inverters";

    upsertChart("chart-power-output", {
      type: "line",
      data: {
        labels,
        datasets: [
          { label: "Avg solar output (kW)", data: series.map(s => s.current_power_kw), borderColor: C.solar, backgroundColor: C.solarSoft, fill: true, tension: 0.35, borderWidth: 2, pointRadius: 0 },
          { label: "Avg load power (kW)", data: series.map(s => s.load_power_kw), borderColor: C.load, backgroundColor: "rgba(176,141,85,0.08)", fill: true, tension: 0.35, borderWidth: 2, pointRadius: 0 }
        ]
      },
      options: baseOptions()
    });

    drawDailyEnergy(series, labels);

    upsertChart("chart-battery-soc", {
      type: "doughnut",
      data: { labels: ["Avg SOC", "Remaining"], datasets: [{ data: [avgSOC, Math.max(0, 100 - avgSOC)], backgroundColor: [avgSOC < 20 ? C.crit : C.solar, "rgba(10,10,10,0.06)"], borderWidth: 0 }] },
      options: { responsive: true, maintainAspectRatio: false, cutout: "75%", plugins: { legend: { display: false }, tooltip: { enabled: false } } },
      plugins: [{
        id: "textInside",
        afterDraw(chart) {
          const value = chart.data.datasets[0].data[0];
          const { width, height, ctx } = chart;
          ctx.save();
          ctx.font = "600 28px Poppins, sans-serif";
          ctx.textBaseline = "middle";
          ctx.fillStyle = C.ink;
          const text = value + "%";
          ctx.fillText(text, Math.round((width - ctx.measureText(text).width) / 2), height / 2);
          ctx.restore();
        }
      }]
    });

    upsertChart("chart-battery-power", {
      type: "line",
      data: { labels, datasets: [{ label: "Avg battery power (kW)", data: series.map(s => s.battery_power_kw), borderColor: C.warn, backgroundColor: "rgba(217,150,46,0.12)", fill: true, tension: 0.3, borderWidth: 2, pointRadius: 0 }] },
      options: Object.assign(baseOptions(), { plugins: { legend: { display: false } }, scales: { x: { grid: { display: false } }, y: { grid: { color: "rgba(10,10,10,0.05)" } } } })
    });

    upsertChart("chart-grid-power", {
      type: "bar",
      data: { labels, datasets: [{ label: "Avg grid power (kW)", data: series.map(s => s.grid_power_kw), backgroundColor: C.crit, borderRadius: 6 }] },
      options: Object.assign(baseOptions(), { plugins: { legend: { display: false } }, scales: { x: { grid: { display: false } }, y: { grid: { color: "rgba(10,10,10,0.05)" } } } })
    });
  }

  // Multi-day periods: one bar per day of station solar energy (dark = GoodWe's own daily
  // total fetched from SEMS+, light = estimated from readings). Single day: the running total.
  function drawDailyEnergy(series, labels) {
    const energy = energyByDate();
    const dayKeys = [];
    for (let d = state.range.from; d <= state.range.to; d = addDays(d, 1)) dayKeys.push(d);
    const useDaily = dayKeys.length > 1 && dayKeys.some(d => energy[d] && energy[d].solar_kwh > 0);
    const meta = document.getElementById("daily-energy-meta");
    if (!useDaily && !series.length) {
      if (charts["chart-daily-energy"]) { charts["chart-daily-energy"].destroy(); delete charts["chart-daily-energy"]; }
      meta.textContent = "No readings in this period";
      return;
    }
    const official = d => energy[d] && energy[d].source && energy[d].source !== "Readings";
    const hasOfficial = useDaily && dayKeys.some(official);
    meta.textContent = !useDaily ? "Avg kWh per inverter, running total"
      : hasOfficial ? "kWh per day (dark: GoodWe daily total, light: from readings)" : "Station kWh per day";
    upsertChart("chart-daily-energy", {
      type: "bar",
      data: useDaily
        ? { labels: dayKeys.map(d => fmtDate(d)), datasets: [{
            label: "Solar energy (kWh)",
            data: dayKeys.map(d => energy[d] ? energy[d].solar_kwh : null),
            backgroundColor: dayKeys.map(d => official(d) ? "#44631f" : "rgba(122,162,63,0.55)"),
            borderRadius: 6 }] }
        : { labels, datasets: [{ label: "Avg daily energy (kWh)", data: series.map(s => s.daily_energy_kwh), backgroundColor: "#44631f", borderRadius: 6 }] },
      options: Object.assign(baseOptions(), {
        plugins: {
          legend: { display: false },
          tooltip: { callbacks: { afterLabel: ctx => {
            if (!useDaily) return "";
            const e = energy[dayKeys[ctx.dataIndex]];
            return e && e.source ? `Source: ${e.source === "Readings" ? "estimated from readings" : e.source}` : "";
          } } }
        }
      })
    });
  }

  /* ------------------------------------------------------------------
   * Fetch missing days (GoodWe daily totals from SEMS+)
   * ------------------------------------------------------------------ */
  const BACKFILL_API = "upande_goodwe.goodwe.backfill";
  async function loadMissingDays() {
    const btn = document.getElementById("backfill-btn");
    const yesterday = addDays(todayStr(), -1);
    const to = state.range.to < yesterday ? state.range.to : yesterday;
    if (state.range.from > to) { btn.hidden = true; state.missingDays = []; return; }
    try {
      const bySite = await api(`${BACKFILL_API}.missing_days`, { from_date: state.range.from, to_date: to });
      state.missingDays = [].concat(...Object.values(bySite || {}));
      const unique = Array.from(new Set(state.missingDays));
      btn.hidden = unique.length === 0;
      btn.textContent = `Fetch ${unique.length} missing day${unique.length === 1 ? "" : "s"}`;
    } catch (e) {
      btn.hidden = true; // backfill module not deployed or no permission
    }
  }
  async function runBackfill() {
    const btn = document.getElementById("backfill-btn");
    const yesterday = addDays(todayStr(), -1);
    const to = state.range.to < yesterday ? state.range.to : yesterday;
    btn.disabled = true;
    const label = btn.textContent;
    btn.textContent = "Fetching from SEMS+…";
    try {
      const r = await api(`${BACKFILL_API}.backfill_daily_energy`, { from_date: state.range.from, to_date: to, only_missing: 1 });
      toast((r && r.summary) || "Done");
      await refreshAll();
    } catch (e) {
      toast(e.status === 403 || /not permitted|permission/i.test(e.message)
        ? "Only System Managers can fetch past days" : `Not fetched: ${e.message}`);
      btn.textContent = label;
    } finally {
      btn.disabled = false;
    }
  }

  // Fallbacks when the ro_dashboard API module isn't deployed: derive from the
  // latest 1000 GoodWe readings already loaded (covers fewer days).
  function energyByDate() {
    if (state.energyFromApi) return state.energyFromApi;
    const perInvDay = {};
    state.readings.forEach(r => {
      if (!r.reading_time) return;
      const key = r.inverter + "|" + r.reading_time.slice(0, 10);
      perInvDay[key] = Math.max(perInvDay[key] || 0, Number(r.daily_energy_kwh) || 0);
    });
    const out = {};
    Object.entries(perInvDay).forEach(([k, v]) => {
      const d = k.split("|")[1];
      out[d] = out[d] || { solar_kwh: 0, load_kwh: null };
      out[d].solar_kwh += v;
    });
    return out;
  }
  function solarProfile() {
    if (state.solarProfileFromApi && state.solarProfileFromApi.some(v => v > 0)) return state.solarProfileFromApi;
    if (!state.readings.length) return null;
    const acc = {};
    state.readings.forEach(r => {
      if (!r.reading_time) return;
      const h = parseInt(r.reading_time.slice(11, 13), 10);
      if (!Number.isFinite(h)) return;
      const k = r.inverter + "|" + h;
      acc[k] = acc[k] || { s: 0, n: 0 };
      acc[k].s += Number(r.current_power_kw) || 0; acc[k].n += 1;
    });
    const prof = new Array(24).fill(0);
    Object.entries(acc).forEach(([k, v]) => { prof[parseInt(k.split("|")[1], 10)] += v.s / v.n; });
    return prof.some(v => v > 0) ? prof : null;
  }

  /* ------------------------------------------------------------------
   * Water & RO (manual logs)
   * ------------------------------------------------------------------ */
  // Loads extra days before the period so day-one volumes, 7/30-day baselines and
  // the previous-period comparison all have data.
  function loadWindow() {
    const len = rangeDays(state.range);
    return {
      from: addDays(state.range.from, -Math.max(60, len + 7)),
      to: state.range.to,
      profileFrom: len > 14 ? addDays(state.range.to, -13) : state.range.from
    };
  }

  async function loadWater() {
    state.logsError = null;
    try {
      const w = loadWindow();
      const payload = await api(`${API}.get_dashboard_data`, { site: state.site, from_date: w.from, to_date: w.to, profile_from: w.profileFrom });
      state.logs = payload.logs || [];
      state.energyFromApi = {};
      (payload.daily_energy || []).forEach(e => { state.energyFromApi[String(e.date).slice(0, 10)] = { solar_kwh: num(e.solar_kwh), load_kwh: num(e.load_kwh), source: e.source || null }; });
      state.solarProfileFromApi = payload.solar_profile || null;
      return;
    } catch (e) {
      state.energyFromApi = null;
      state.solarProfileFromApi = null;
    }
    try {
      const w = loadWindow();
      const logs = await api("frappe.client.get_list", {
        doctype: LOG_DOCTYPE, fields: LOG_FIELDS,
        filters: [["site", "=", state.site], ["log_date", "between", [w.from, w.to]]],
        order_by: "log_date asc", limit_page_length: 1500
      });
      state.logs = logs || [];
    } catch (e) {
      state.logs = [];
      state.logsError = e.message || "Could not load readings";
    }
  }

  function buildRows() {
    const energy = energyByDate();
    const cfg = SITE_CONFIG[state.site];
    const sorted = [...state.logs].sort((a, b) => String(a.log_date).localeCompare(String(b.log_date)));
    let prevBh = null, prevSm = null;
    return sorted.map(l => {
      const date = String(l.log_date).slice(0, 10);
      const r = {
        name: l.name, raw: l, date,
        bh: num(l.borehole_meter), sm: num(l.smart_meter),
        permeate: num(l.permeate_m3), reject: num(l.reject_m3), sold: num(l.units_sold),
        rw: num(l.rw_tank_level), tw: num(l.tw_tank_level),
        pumped: null, pumpedSmart: null, gap: 1
      };
      if (r.bh != null && prevBh) {
        const gap = dayDiff(prevBh.date, date);
        if (gap > 0) { r.pumped = (r.bh - prevBh.value) / gap; r.gap = gap; }
      }
      if (r.sm != null && prevSm) {
        const gap = dayDiff(prevSm.date, date);
        if (gap > 0) r.pumpedSmart = (r.sm - prevSm.value) / gap;
      }
      if (r.bh != null) prevBh = { date, value: r.bh };
      if (r.sm != null) prevSm = { date, value: r.sm };

      r.deviation = r.pumped > 0 && r.pumpedSmart != null ? (r.pumpedSmart - r.pumped) / r.pumped * 100 : null;
      r.feed = r.permeate != null && r.reject != null ? r.permeate + r.reject : null;
      r.recovery = r.feed > 0 ? r.permeate / r.feed * 100 : null;
      // Water supplied to the estate: permeate where there is an RO, else borehole water.
      r.supplied = cfg.hasRO ? r.permeate : r.pumped;
      r.nrw = r.supplied != null && r.sold != null ? r.supplied - r.sold : null;
      r.nrwPct = r.supplied > 0 && r.nrw != null ? r.nrw / r.supplied * 100 : null;
      r.soldRatio = r.pumped > 0 && r.sold != null ? r.sold / r.pumped * 100 : null;
      r.tankBalance = cfg.hasRO && r.pumped != null && r.feed != null ? r.pumped - r.feed : null;
      const e = energy[date];
      r.energyKwh = e ? (e.load_kwh > 0 ? e.load_kwh : e.solar_kwh) : null;
      r.kwhPerM3 = r.pumped > 0 && r.energyKwh > 0 ? r.energyKwh / r.pumped : null;
      r.flags = rowFlags(r);
      return r;
    });
  }

  function rowFlags(r) {
    const s = state.settings, f = {};
    if (r.deviation != null) {
      const off = Math.abs(r.deviation - s.devExpected);
      if (off > 2 * s.devTolerance) f.deviation = "critical"; else if (off > s.devTolerance) f.deviation = "warning";
    }
    if (r.recovery != null) {
      if (r.recovery < s.recoveryTarget - 10) f.recovery = "critical"; else if (r.recovery < s.recoveryTarget - 3) f.recovery = "warning";
    }
    if (r.nrwPct != null) {
      if (r.nrwPct > s.nrwCritical) f.nrwPct = "critical"; else if (r.nrwPct > s.nrwWarn || r.nrwPct < -5) f.nrwPct = "warning";
    }
    return f;
  }

  /* ------------------------------------------------------------------
   * Water KPIs, charts and table
   * ------------------------------------------------------------------ */
  function setKpi(id, value, decimals, deltaText, deltaClass, flag) {
    const card = document.getElementById(id);
    card.querySelector("[data-v]").textContent = format(value, decimals);
    const d = card.querySelector("[data-d]");
    d.textContent = deltaText || "";
    d.className = "kpi__delta" + (deltaClass ? " " + deltaClass : "");
    card.classList.remove("kpi--flag-warning", "kpi--flag-critical");
    if (flag) card.classList.add("kpi--flag-" + flag);
  }
  // Compares the latest value with the average of the 7 values before it.
  function versusWeek(rows, key, goodWhenUp) {
    const vals = rows.map(r => r[key]);
    let i = vals.length - 1; while (i >= 0 && vals[i] == null) i--;
    if (i < 0) return { value: null, text: "", cls: "" };
    const latest = vals[i];
    const prior = mean(vals.slice(Math.max(0, i - 7), i));
    if (prior == null || prior === 0) return { value: latest, text: "", cls: "" };
    const ch = (latest - prior) / Math.abs(prior) * 100;
    const arrow = ch > 0.5 ? "▲" : ch < -0.5 ? "▼" : "■";
    let cls = "flat";
    if (goodWhenUp === true) cls = ch > 2 ? "up" : ch < -2 ? "down" : "flat";
    if (goodWhenUp === false) cls = ch > 2 ? "down" : ch < -2 ? "up" : "flat";
    return { value: latest, text: `${arrow} ${format(Math.abs(ch), 0)}% vs 7-day avg (${format(prior, 1)})`, cls, row: rows[i] };
  }

  // Period totals: ratios are computed from summed volumes, not averaged percentages.
  function aggregate(rows) {
    const both = (a, b) => rows.filter(r => r[a] != null && r[b] != null);
    const sumOf = (rs, k) => sum(rs.map(r => r[k]));
    const pumpedRows = rows.filter(r => r.pumped != null);
    const recRows = both("permeate", "reject");
    const nrwRows = both("supplied", "sold");
    const devRows = both("pumped", "pumpedSmart");
    const enRows = both("pumped", "energyKwh").filter(r => r.energyKwh > 0);
    return {
      days: rows.length,
      pumped: pumpedRows.length ? sumOf(pumpedRows, "pumped") : null,
      pumpedAvg: pumpedRows.length ? mean(pumpedRows.map(r => r.pumped)) : null,
      sold: rows.some(r => r.sold != null) ? sumOf(rows, "sold") : null,
      recovery: recRows.length && sumOf(recRows, "feed") > 0 ? sumOf(recRows, "permeate") / sumOf(recRows, "feed") * 100 : null,
      nrwPct: nrwRows.length && sumOf(nrwRows, "supplied") > 0 ? sumOf(nrwRows, "nrw") / sumOf(nrwRows, "supplied") * 100 : null,
      nrwM3: nrwRows.length ? sumOf(nrwRows, "nrw") : null,
      deviation: devRows.length && sumOf(devRows, "pumped") > 0 ? (sumOf(devRows, "pumpedSmart") - sumOf(devRows, "pumped")) / sumOf(devRows, "pumped") * 100 : null,
      kwhPerM3: enRows.length ? sumOf(enRows, "energyKwh") / sumOf(enRows, "pumped") : null
    };
  }
  function compareText(cur, prev, goodWhenUp, label, points) {
    if (cur == null || prev == null || (!points && prev === 0)) return { text: "", cls: "" };
    const ch = points ? cur - prev : (cur - prev) / Math.abs(prev) * 100;
    const arrow = ch > 0.05 ? "▲" : ch < -0.05 ? "▼" : "■";
    let cls = "flat";
    if (goodWhenUp === true) cls = ch > 2 ? "up" : ch < -2 ? "down" : "flat";
    if (goodWhenUp === false) cls = ch > 2 ? "down" : ch < -2 ? "up" : "flat";
    return { text: `${arrow} ${format(Math.abs(ch), points ? 1 : 0)}${points ? " pts" : "%"} vs ${label}`, cls };
  }

  function renderWater() {
    const all = state.rows, cfg = SITE_CONFIG[state.site], s = state.settings;
    const view = inRange(all);
    const len = rangeDays(state.range);
    const single = isSingleDay();
    const logged = view.length;
    document.getElementById("water-asof").innerHTML = `${escapeHtml(state.site)}, ${escapeHtml(rangeText(state.range))}` +
      (single ? (logged ? "" : ", not logged") : `, ${logged} of ${len} days logged`) +
      (isLive() ? "" : `<span class="pill-hist">Past period</span>`);

    if (single) {
      // One day: that day's value against the 7 logged days before it.
      const rows = upToEnd(all);
      const day = view[0];
      const vs = (key, good) => day && day[key] != null ? versusWeek(rows, key, good) : { value: null, text: "", cls: "" };
      const p = vs("pumped", null);
      setKpi("kpi-pumped", p.value, 0, p.text || (day && day.gap > 1 ? `Averaged over ${day.gap} days` : (day ? "" : "Not logged")), p.cls);
      if (cfg.hasRO) {
        const r = vs("recovery", true);
        setKpi("kpi-recovery", r.value, 1, r.value != null ? `Target ${format(s.recoveryTarget, 1)}%  ${r.text}` : "Log reject volume to calculate", r.cls, day && day.flags.recovery);
      } else setKpi("kpi-recovery", null, 1, "No RO plant at this site", "");
      const so = vs("sold", true);
      setKpi("kpi-sold", so.value, 0, so.text, so.cls);
      const n = vs("nrwPct", false);
      setKpi("kpi-nrw", n.value, 1, n.value != null ? n.text : (cfg.hasRO ? "Log permeate and sales to calculate" : "Log borehole and sales to calculate"), n.cls, day && day.flags.nrwPct);
      if (cfg.hasSmartMeter) setKpi("kpi-deviation", day && day.deviation, 1, `Expected ${format(s.devExpected, 1)} ± ${format(s.devTolerance, 1)}`, "flat", day && day.flags.deviation);
      else setKpi("kpi-deviation", null, 1, "No smart meter at this site", "");
      const en = vs("kwhPerM3", false);
      setKpi("kpi-energy", en.value, 2, en.value != null ? en.text : "Needs GoodWe energy for this day", en.cls);
    } else {
      // A period: totals and volume-weighted ratios against the previous period of the same length.
      const prevRange = { from: addDays(state.range.from, -len), to: addDays(state.range.from, -1) };
      const prevRows = all.filter(r => r.date >= prevRange.from && r.date <= prevRange.to);
      const a = aggregate(view), b = aggregate(prevRows);
      const label = `previous ${len} days`;
      const flagFor = (v, warnBelow, critBelow) => v == null ? null : v < critBelow ? "critical" : v < warnBelow ? "warning" : null;

      const p = compareText(a.pumped, b.pumped, null, label);
      setKpi("kpi-pumped", a.pumped, 0, a.pumped != null ? `${format(a.pumpedAvg, 0)} m³/day  ${p.text}` : "No borehole readings", p.cls);
      if (cfg.hasRO) {
        const r = compareText(a.recovery, b.recovery, true, label, true);
        setKpi("kpi-recovery", a.recovery, 1, a.recovery != null ? `Target ${format(s.recoveryTarget, 1)}%  ${r.text}` : "No days with permeate and reject", r.cls,
          flagFor(a.recovery, s.recoveryTarget - 3, s.recoveryTarget - 10));
      } else setKpi("kpi-recovery", null, 1, "No RO plant at this site", "");
      const so = compareText(a.sold, b.sold, true, label);
      setKpi("kpi-sold", a.sold, 0, so.text, so.cls);
      const n = compareText(a.nrwPct, b.nrwPct, false, label, true);
      setKpi("kpi-nrw", a.nrwPct, 1, a.nrwPct != null ? `${a.nrwM3 >= 0 ? format(a.nrwM3, 0) + " m³ unbilled" : format(-a.nrwM3, 0) + " m³ more sold than supplied"}  ${n.text}` : "Not enough data in this period", n.cls,
        a.nrwPct == null ? null : a.nrwPct > s.nrwCritical ? "critical" : a.nrwPct > s.nrwWarn ? "warning" : null);
      if (cfg.hasSmartMeter) {
        const off = a.deviation == null ? 0 : Math.abs(a.deviation - s.devExpected);
        setKpi("kpi-deviation", a.deviation, 1, `Expected ${format(s.devExpected, 1)} ± ${format(s.devTolerance, 1)}`, "flat",
          off > 2 * s.devTolerance ? "critical" : off > s.devTolerance ? "warning" : null);
      } else setKpi("kpi-deviation", null, 1, "No smart meter at this site", "");
      const en = compareText(a.kwhPerM3, b.kwhPerM3, false, label);
      setKpi("kpi-energy", a.kwhPerM3, 2, a.kwhPerM3 != null ? en.text : "Needs GoodWe energy for logged days", en.cls);
    }

    // Charts show the selected period
    const labels = view.map(r => fmtDate(r.date));

    // 1. Water balance
    const hasAny = view.some(r => r.pumped != null || r.sold != null);
    setEmpty("water-balance", !hasAny);
    document.getElementById("empty-water-balance").textContent = all.length
      ? "No readings logged in this period. Pick another period or log the missing days."
      : "No readings logged yet for this site. Log the first day to start the balance.";
    const datasets = [{ type: "bar", label: "Sold", data: view.map(r => r.sold), backgroundColor: C.water, borderRadius: 4, stack: "w" }];
    if (cfg.hasRO) {
      datasets.push({ type: "bar", label: "Non-revenue (permeate − sold)", data: view.map(r => r.nrw != null ? Math.max(0, r.nrw) : null), backgroundColor: C.warn, borderRadius: 4, stack: "w" });
      datasets.push({ type: "bar", label: "RO reject", data: view.map(r => r.reject), backgroundColor: "rgba(10,10,10,0.14)", borderRadius: 4, stack: "w" });
      datasets.push({ type: "bar", label: "Not split (no RO volumes logged)", data: view.map(r => r.permeate == null && r.pumped != null && r.sold != null ? Math.max(0, r.pumped - r.sold) : null), backgroundColor: "rgba(43,111,158,0.18)", borderRadius: 4, stack: "w" });
    } else {
      datasets.push({ type: "bar", label: "Unbilled (pumped − sold)", data: view.map(r => r.nrw != null ? Math.max(0, r.nrw) : null), backgroundColor: C.warn, borderRadius: 4, stack: "w" });
    }
    datasets.push({ type: "line", label: "Pumped from borehole", data: view.map(r => r.pumped), borderColor: C.ink, backgroundColor: C.ink, borderWidth: 2, pointRadius: 2, tension: 0.25, spanGaps: true });
    const wbOpts = baseOptions();
    wbOpts.scales.x.stacked = true; wbOpts.scales.y.stacked = true;
    upsertChart("chart-water-balance", { type: "bar", data: { labels, datasets }, options: wbOpts });

    // 2. RO recovery
    const rec = view.map(r => r.recovery);
    setEmpty("ro-recovery", !cfg.hasRO || !rec.some(v => v != null));
    upsertChart("chart-ro-recovery", {
      type: "line",
      data: {
        labels, datasets: [
          { label: "Recovery %", data: rec, borderColor: C.water, backgroundColor: C.waterSoft, fill: true, tension: 0.3, borderWidth: 2, spanGaps: true, pointRadius: 2 },
          { label: "7-day average", data: rolling(rec, 7), borderColor: C.ink, borderWidth: 1.5, pointRadius: 0, tension: 0.3, spanGaps: true },
          { label: "Target", data: view.map(() => s.recoveryTarget), borderColor: C.signal, borderDash: [6, 4], borderWidth: 1.5, pointRadius: 0 }
        ]
      },
      options: Object.assign(baseOptions(), { scales: { x: { grid: { display: false } }, y: { suggestedMin: 40, suggestedMax: 90, grid: { color: "rgba(10,10,10,0.05)" } } } })
    });

    // 3. Meter deviation
    const dev = view.map(r => r.deviation);
    setEmpty("meter-dev", !cfg.hasSmartMeter || !dev.some(v => v != null));
    upsertChart("chart-meter-dev", {
      type: "line",
      data: {
        labels, datasets: [
          { label: "Deviation %", data: dev, borderColor: C.water, borderWidth: 2, tension: 0.25, spanGaps: true, pointRadius: 3,
            pointBackgroundColor: view.map(r => r.flags.deviation === "critical" ? C.crit : r.flags.deviation === "warning" ? C.warn : C.water) },
          { label: "Upper limit", data: view.map(() => s.devExpected + s.devTolerance), borderColor: C.mute, borderDash: [5, 4], borderWidth: 1, pointRadius: 0, fill: "+1", backgroundColor: "rgba(34,136,131,0.06)" },
          { label: "Lower limit", data: view.map(() => s.devExpected - s.devTolerance), borderColor: C.mute, borderDash: [5, 4], borderWidth: 1, pointRadius: 0 }
        ]
      },
      options: Object.assign(baseOptions(), { scales: { x: { grid: { display: false } }, y: { grid: { color: "rgba(10,10,10,0.05)" } } } })
    });

    // 4. Demand vs solar
    const prof = solarProfile();
    const profTotal = prof ? prof.reduce((a, b) => a + b, 0) : 0;
    const solarShare = prof && profTotal > 0 ? prof.map(v => v / profTotal * 100) : null;
    const dsSets = [{ type: "bar", label: "Estate demand (% of day)", data: BASELINE_DEMAND, backgroundColor: C.waterSoft, borderColor: C.water, borderWidth: 1, borderRadius: 4 }];
    if (solarShare) dsSets.push({ type: "line", label: "Solar output (% of day)", data: solarShare, borderColor: C.solar, backgroundColor: C.solarSoft, fill: true, tension: 0.35, borderWidth: 2, pointRadius: 0 });
    upsertChart("chart-demand-solar", { type: "bar", data: { labels: BASELINE_DEMAND.map((_, h) => `${pad(h)}:00`), datasets: dsSets }, options: baseOptions() });
    const align = solarAlignment(prof);
    document.getElementById("demand-solar-note").textContent = align
      ? `${format(align.demandShare, 0)}% of demand falls between ${pad(align.start)}:00 and ${pad(align.end + 1)}:00, when solar is above a quarter of its peak. Demand shape from the August 2026 hourly study.`
      : "Demand shape from the August 2026 hourly study. Solar overlay appears once GoodWe readings span the day.";

    // 5. Energy intensity
    const ei = view.map(r => r.kwhPerM3);
    setEmpty("energy-intensity", !ei.some(v => v != null));
    upsertChart("chart-energy-intensity", {
      type: "bar",
      data: { labels, datasets: [
        { type: "bar", label: "kWh per m³", data: ei, backgroundColor: C.solar, borderRadius: 4 },
        { type: "line", label: "7-day average", data: rolling(ei, 7), borderColor: C.ink, borderWidth: 1.5, pointRadius: 0, tension: 0.3, spanGaps: true }
      ] },
      options: baseOptions()
    });

    renderTable(view);
  }

  function solarAlignment(prof) {
    if (!prof) return null;
    const peak = Math.max(...prof);
    if (peak <= 0) return null;
    const hours = prof.map((v, h) => (v >= peak * 0.25 ? h : null)).filter(h => h != null);
    if (!hours.length) return null;
    const start = Math.min(...hours), end = Math.max(...hours);
    let demandShare = 0;
    for (let h = start; h <= end; h++) demandShare += BASELINE_DEMAND[h];
    return { start, end, demandShare, peakHour: prof.indexOf(peak) };
  }

  function renderTable(rows) {
    const body = document.getElementById("logs-body");
    const toggle = document.getElementById("toggle-rows");
    toggle.hidden = true;
    if (state.logsError) {
      body.innerHTML = `<tr><td colspan="12" class="muted">${escapeHtml(state.logsError)}</td></tr>`;
      return;
    }
    document.getElementById("table-meta").textContent = `${rows.length} logged day${rows.length === 1 ? "" : "s"} in ${rangeText(state.range)}. Edit a row, or open any date.`;
    if (!rows.length) {
      body.innerHTML = `<tr><td colspan="12" class="muted">No readings for ${escapeHtml(state.site)} in this period. Use “Log readings” or “Open day” to add one.</td></tr>`;
      return;
    }
    const cell = (v, d, suffix, flag) => v == null
      ? `<td class="muted">—</td>`
      : `<td class="${flag ? "flag-" + flag : ""}">${format(v, d)}${suffix || ""}</td>`;
    const shown = state.showAllRows ? rows.slice().reverse() : rows.slice(-14).reverse();
    body.innerHTML = shown.map(r => `
      <tr data-name="${escapeHtml(r.name)}" data-date="${r.date}" class="${r.name === state.highlightName ? "row-updated" : ""}"
          title="${escapeHtml(r.raw.notes || "Select to edit")}">
        <td>${fmtDate(r.date, true)}${r.gap > 1 ? ` <span class="muted">(${r.gap}d)</span>` : ""}</td>
        ${cell(r.pumped, 1)}${cell(r.pumpedSmart, 1)}${cell(r.deviation, 1, "%", r.flags.deviation)}
        ${cell(r.permeate, 1)}${cell(r.reject, 1)}${cell(r.recovery, 1, "%", r.flags.recovery)}
        ${cell(r.sold, 0)}${cell(r.nrwPct, 1, "%", r.flags.nrwPct)}${cell(r.soldRatio, 0, "%")}${cell(r.kwhPerM3, 2)}
        <td><button class="rowbtn" type="button" aria-label="Edit ${fmtDate(r.date, true)}">Edit</button></td>
      </tr>`).join("");
    body.querySelectorAll("tr[data-date]").forEach(tr => {
      tr.addEventListener("click", () => openLogModal(tr.dataset.date));
    });
    if (rows.length > 14) {
      toggle.hidden = false;
      toggle.textContent = state.showAllRows ? "Show latest 14 days" : `Show all ${rows.length} days in this period`;
    }
    state.highlightName = null;
  }

  /* ------------------------------------------------------------------
   * Insight engine
   * ------------------------------------------------------------------ */
  const SEV_ORDER = { critical: 0, warning: 1, info: 2, good: 3 };

  function generateInsights() {
    // Insights are worked out as of the end of the selected period.
    const rows = upToEnd(state.rows), s = state.settings, cfg = SITE_CONFIG[state.site];
    const out = [];
    const add = (sev, title, body, action, tag) => out.push({ sev, title, body, action, tag });
    const live = isLive();
    const today = live ? todayStr() : addDays(state.range.to, 1);

    // --- Data availability
    if (state.logsError) {
      add("critical", "Water readings can't be loaded",
        `The dashboard couldn't read the ${LOG_DOCTYPE} records: ${state.logsError}.`,
        `Install the ${LOG_DOCTYPE} DocType and make sure your role can read it, then refresh.`, "Setup");
    } else if (!rows.length) {
      add("info", `No readings logged for ${state.site} yet`,
        "Insights on RO recovery, meter accuracy and non-revenue water start once a few days are logged.",
        "Log yesterday's readings, or import the workbook history with the provided CSV.", "Data");
    } else if (live) {
      const lastDate = rows[rows.length - 1].date;
      const behind = dayDiff(lastDate, today) - 1; // readings for yesterday are expected today
      if (behind >= 1) {
        add(behind >= 3 ? "critical" : "warning",
          `Readings are ${behind} day${behind > 1 ? "s" : ""} behind`,
          `The last logged day is ${fmtDate(lastDate, true)}. Gaps get averaged across days, which hides leaks and pump faults.`,
          "Read the meters tomorrow morning and log them here; multi-day gaps can be filled from the meter totals.", "Data");
      }
    }

    // --- Coverage of the selected period
    if (!state.logsError && rows.length && rangeDays(state.range) > 1) {
      const len = rangeDays(state.range);
      const logged = inRange(rows).length;
      if (logged < len * 0.8) {
        add(logged === 0 ? "warning" : "info", `${logged} of ${len} days logged in this period`,
          "Totals and averages for the period only cover the logged days; missing days are averaged into the next reading.",
          "Use “Open day” to fill the gaps from the meter totals.", "Data");
      }
    }

    // --- Smart vs mechanical meter
    if (cfg.hasSmartMeter) {
      const devRows = rows.filter(r => r.deviation != null).slice(-7);
      if (devRows.length) {
        const latest = devRows[devRows.length - 1];
        const avg = mean(devRows.map(r => r.deviation));
        const off = latest.deviation - s.devExpected;
        if (latest.flags.deviation) {
          const below = latest.deviation < 0;
          add(latest.flags.deviation,
            below ? `Smart meter read below the mechanical meter on ${fmtDate(latest.date)}`
                  : `Meters disagree by ${format(latest.deviation, 1)}% on ${fmtDate(latest.date)}`,
            `Normally the Ubuntu smart meter reads about ${format(s.devExpected, 1)}% above the borehole meter; it is ${format(Math.abs(off), 1)} points ${off > 0 ? "higher" : "lower"} than that. 7-day average: ${format(avg, 1)}%.`,
            below ? "A negative gap usually means a mistyped reading — check the logged values before anything else."
                  : "Re-read both meters tomorrow. If the gap persists, check for air in the line, a sticking mechanical dial or smart-meter calibration.",
            "Meters");
        } else if (devRows.length >= 3) {
          add("good", "Meters agree within the normal band",
            `Smart vs mechanical deviation averaged ${format(avg, 1)}% over the last ${devRows.length} readings (expected ${format(s.devExpected, 1)} ± ${format(s.devTolerance, 1)}).`,
            null, "Meters");
        }
      }
    }

    // --- RO recovery
    if (cfg.hasRO && rows.length) {
      const recent = rows.slice(-14);
      const recRows = recent.filter(r => r.recovery != null);
      if (!recRows.length) {
        add("info", "RO recovery isn't being tracked",
          "No days in the last two weeks have both permeate and reject volumes, so membrane performance can't be followed.",
          "Log the reject meter together with the booster-pump meter each morning.", "RO");
      } else {
        const latest = recRows[recRows.length - 1];
        const prior = mean(recRows.slice(0, -1).slice(-7).map(r => r.recovery));
        const drop = prior != null ? prior - latest.recovery : 0;
        const feedAvg = mean(recRows.map(r => r.feed));
        const perPoint = feedAvg ? feedAvg / 100 : null;
        if (latest.flags.recovery || drop > 5) {
          add(latest.flags.recovery || "warning",
            drop > 5 ? `RO recovery fell ${format(drop, 1)} points to ${format(latest.recovery, 1)}%`
                     : `RO recovery below target at ${format(latest.recovery, 1)}%`,
            `Target is ${format(s.recoveryTarget, 1)}%${prior != null ? `, recent average ${format(prior, 1)}%` : ""}.` +
              (perPoint ? ` Each point lost sends about ${format(perPoint, 1)} m³ a day to reject instead of the estate.` : ""),
            "Check feed pressure and the pre-filter pressure drop. A drop that holds for several days usually means fouling and a membrane clean (CIP) is due.",
            "RO");
        } else {
          add("good", `RO recovery on track at ${format(latest.recovery, 1)}%`,
            `Target ${format(s.recoveryTarget, 1)}%${prior != null ? `, recent average ${format(prior, 1)}%` : ""}.`, null, "RO");
        }

        // Tank / pre-RO balance
        const bal = recent.filter(r => r.tankBalance != null);
        if (bal.length >= 3) {
          const avgBal = mean(bal.map(r => r.tankBalance));
          const avgPumped = mean(bal.map(r => r.pumped));
          if (avgPumped && Math.abs(avgBal) > avgPumped * 0.1) {
            add("info", `Borehole and RO feed differ by ${format(Math.abs(avgBal), 0)} m³ a day`,
              avgBal > 0
                ? "More water leaves the borehole than enters the RO. It is either filling the raw-water tank or being lost before the plant."
                : "The RO is treating more than the borehole delivers, so the raw-water tank is being drawn down.",
              "Log raw and treated tank levels so storage changes can be separated from losses.", "Balance");
          }
        }
      }
    }

    // --- Non-revenue water
    // Only use the last two weeks of logged days so old history doesn't pose as "recent".
    const nrwRows = rows.slice(-14).filter(r => r.nrwPct != null).slice(-7);
    if (nrwRows.length >= 2) {
      const avg = mean(nrwRows.map(r => r.nrwPct));
      const lostM3 = sum(nrwRows.map(r => Math.max(0, r.nrw)));
      const priorRows = rows.slice(-28, -14).filter(r => r.nrwPct != null).slice(-7);
      const priorAvg = priorRows.length ? mean(priorRows.map(r => r.nrwPct)) : null;
      const perDay = lostM3 / nrwRows.length;
      const money = s.tariff > 0 ? ` That is roughly KES ${format(perDay * 30 * s.tariff, 0)} a month at the current tariff.` : "";
      const trend = priorAvg != null ? ` Previous week: ${format(priorAvg, 1)}%.` : "";
      const negDays = nrwRows.filter(r => r.nrwPct < -5);
      if (negDays.length) {
        add("warning", `Sales exceeded water supplied on ${negDays.length} of the last ${nrwRows.length} days`,
          `Latest: ${fmtDate(negDays[negDays.length - 1].date)}, ${format(negDays[negDays.length - 1].sold, 0)} m³ sold against ${format(negDays[negDays.length - 1].supplied, 0)} m³ supplied. Billing can't exceed supply, so one of the figures is off.`,
          "Check whether the sales figure covers a different period (e.g. token sales vs consumption) and that the supply meter reading was entered correctly.", "NRW");
      }
      const sev = avg > s.nrwCritical ? "critical" : avg > s.nrwWarn ? "warning" : "good";
      add(sev, `Non-revenue water at ${format(avg, 1)}% over the last ${nrwRows.length} days`,
        `${format(lostM3, 0)} m³ supplied${cfg.hasRO ? " to the estate" : ""} wasn't billed.${money}${trend}`,
        sev === "good" ? null
          : `Walk the distribution lines during peak hours (10:00–13:00, when demand is highest) and check for unmetered connections.${s.tariff > 0 ? "" : " Set a tariff in ⚙ to see the shilling value."}`,
        "NRW");
    }

    // --- Sold ÷ pumped (overall plant yield)
    const ratioNow = rows.slice(-7).filter(r => r.soldRatio != null);
    const ratioPrev = rows.slice(-14, -7).filter(r => r.soldRatio != null);
    if (ratioNow.length >= 3) {
      const a = sum(ratioNow.map(r => r.sold)) / sum(ratioNow.map(r => r.pumped)) * 100;
      const b = ratioPrev.length >= 3 ? sum(ratioPrev.map(r => r.sold)) / sum(ratioPrev.map(r => r.pumped)) * 100 : null;
      const falling = b != null && b - a > 5;
      const impossible = cfg.hasRO && a > s.recoveryTarget + 5;
      add(falling || impossible ? "warning" : "info",
        impossible ? `Billed water (${format(a, 0)}% of borehole) is more than the RO can deliver`
                   : `${format(a, 0)}% of borehole water was billed this week`,
        (impossible ? `With recovery around ${format(s.recoveryTarget, 1)}%, sales should stay below that share of borehole water. ` : "") +
          (b != null ? `Last week: ${format(b, 0)}%.` : "Not enough data for a week-on-week comparison yet."),
        impossible ? "The borehole meter is probably under-reading (the smart meter reads higher too), or sales cover a different period than the meter readings. Compare against the smart meter and confirm how sales are counted."
          : falling ? "Look at which part of the chain changed: recovery (RO), meter deviation, or non-revenue water." : null,
        "Yield");
    }

    // --- Unusual pumping
    const pumpedRows = rows.filter(r => r.pumped != null);
    if (pumpedRows.length >= 10) {
      const latest = pumpedRows[pumpedRows.length - 1];
      const hist = pumpedRows.slice(-31, -1).map(r => r.pumped);
      const m = mean(hist), sd = stdev(hist);
      if (sd && sd > 0) {
        const z = (latest.pumped - m) / sd;
        if (Math.abs(z) >= 2) {
          add("warning",
            `Unusually ${z > 0 ? "high" : "low"} pumping on ${fmtDate(latest.date)}`,
            `${format(latest.pumped, 0)} m³ against a 30-day norm of ${format(m, 0)} ± ${format(sd, 0)} m³.`,
            z > 0 ? "If sales didn't rise as well, check for a burst, an overflowing tank or a stuck float valve."
                  : "Check for pump downtime, a power outage or a misread meter.",
            "Pumping");
        }
      }
    }

    // --- Demand forecast by weekday
    const soldRows = rows.filter(r => r.sold != null).slice(-56);
    if (live && soldRows.length >= 14) {
      const overall = mean(soldRows.map(r => r.sold));
      const tomorrow = addDays(today, 1);
      const wd = weekday(tomorrow);
      const same = soldRows.filter(r => weekday(r.date) === wd).map(r => r.sold);
      if (same.length >= 2 && overall) {
        const f = mean(same);
        const diff = (f - overall) / overall * 100;
        add("info", `Expect about ${format(f, 0)} m³ of sales tomorrow`,
          `${WEEKDAYS[wd]}s have averaged ${format(Math.abs(diff), 0)}% ${diff >= 0 ? "above" : "below"} the weekly mean over the last ${Math.round(soldRows.length / 7)} weeks.`,
          diff > 10 ? "Start the day with the treated-water tank full." : null, "Forecast");
      }
    }

    // --- Solar alignment and energy
    const align = solarAlignment(solarProfile());
    if (align) {
      add("info", `${format(align.demandShare, 0)}% of estate demand falls in solar hours`,
        `Solar output peaks around ${pad(align.peakHour)}:00 and is useful from ${pad(align.start)}:00 to ${pad(align.end + 1)}:00. Evening demand (17:00–22:00) is about ${format(BASELINE_DEMAND.slice(17, 22).reduce((a, b) => a + b, 0), 0)}% of the day.`,
        `Run the borehole pump${cfg.hasRO ? " and RO" : ""} hardest between ${pad(align.start)}:00 and ${pad(align.end + 1)}:00 and fill the treated-water tank, so evenings are served from storage instead of the battery or grid.`,
        "Solar");
    }
    const eRows = rows.filter(r => r.kwhPerM3 != null).slice(-14);
    if (eRows.length >= 5) {
      const latest = eRows[eRows.length - 1];
      const avg = mean(eRows.slice(0, -1).map(r => r.kwhPerM3));
      if (avg && latest.kwhPerM3 > avg * 1.25) {
        add("warning", `Energy per m³ up ${format((latest.kwhPerM3 / avg - 1) * 100, 0)}%`,
          `${format(latest.kwhPerM3, 2)} kWh/m³ on ${fmtDate(latest.date)} against a recent ${format(avg, 2)} kWh/m³.`,
          "Check whether the pump is cycling or running against a closed valve, and whether other loads were on the solar system that day.", "Energy");
      }
    }
    if (live && state.solarLatest && state.solarLatest.avgSOC < 20) {
      add("warning", `Battery bank at ${state.solarLatest.avgSOC}%`,
        "Average state of charge across inverters is low.",
        "Hold non-essential pumping until midday solar is available.", "Solar");
    }

    // --- Month to date vs last month (as in the workbook's monthly summary)
    const mtd = monthCompare(rows, state.range.to);
    if (mtd) add("info", `${mtd.label}: ${format(mtd.sold, 0)} m³ sold`, mtd.text, null, "Monthly");

    out.sort((a, b) => SEV_ORDER[a.sev] - SEV_ORDER[b.sev]);
    return out;
  }

  function monthCompare(rows, refDate) {
    const today = refDate || todayStr();
    const ym = today.slice(0, 7);
    const dayOfMonth = parseInt(today.slice(8, 10), 10);
    const prevMonth = addDays(ym + "-01", -1).slice(0, 7);
    const cur = rows.filter(r => r.date.startsWith(ym));
    const prev = rows.filter(r => r.date.startsWith(prevMonth) && parseInt(r.date.slice(8, 10), 10) <= dayOfMonth);
    if (cur.filter(r => r.sold != null).length < 3) return null;
    const soldCur = sum(cur.map(r => r.sold)), pumpedCur = sum(cur.filter(r => r.sold != null).map(r => r.pumped));
    const soldPrev = sum(prev.map(r => r.sold)), pumpedPrev = sum(prev.filter(r => r.sold != null).map(r => r.pumped));
    const effCur = pumpedCur ? soldCur / pumpedCur * 100 : null;
    const effPrev = pumpedPrev ? soldPrev / pumpedPrev * 100 : null;
    let text = effCur != null ? `${format(effCur, 0)}% of pumped water billed.` : "";
    if (soldPrev) {
      const ch = (soldCur - soldPrev) / soldPrev * 100;
      text += ` Sales are ${format(Math.abs(ch), 0)}% ${ch >= 0 ? "up" : "down"} on the same days last month${effPrev != null ? ` (billed share then: ${format(effPrev, 0)}%)` : ""}.`;
    }
    const label = ym === todayStr().slice(0, 7) ? "Month to date"
      : `${new Date(toUTC(ym + "-01")).toLocaleDateString("en-GB", { month: "long", year: "numeric", timeZone: "UTC" })} to ${fmtDate(today)}`;
    return { sold: soldCur, text: text.trim(), label };
  }

  function renderInsights() {
    const list = generateInsights();
    const el = document.getElementById("insight-list");
    el.innerHTML = list.length ? list.map(i => `
      <div class="insight insight--${i.sev}">
        <span class="insight__dot" aria-hidden="true"></span>
        <div>
          <p class="insight__title">${escapeHtml(i.title)}</p>
          <p class="insight__body">${escapeHtml(i.body)}</p>
          ${i.action ? `<p class="insight__action"><b>Next step:</b> ${escapeHtml(i.action)}</p>` : ""}
        </div>
        <span class="insight__tag">${escapeHtml(i.tag || "")}</span>
      </div>`).join("")
      : `<div class="insight insight--good"><span class="insight__dot"></span><div><p class="insight__title">Nothing needs attention</p><p class="insight__body">All tracked metrics are within their normal ranges.</p></div><span></span></div>`;

    const crit = list.filter(i => i.sev === "critical").length;
    const warn = list.filter(i => i.sev === "warning").length;
    const score = Math.max(0, Math.min(100, 100 - crit * 22 - warn * 9));
    const bar = document.getElementById("health-bar");
    const circ = 2 * Math.PI * 72;
    bar.style.strokeDashoffset = String(circ * (1 - score / 100));
    bar.style.stroke = score >= 85 ? C.solar : score >= 65 ? C.warn : C.crit;
    document.getElementById("health-score").textContent = score;
    document.getElementById("health-label").textContent = score >= 85 ? "Running well" : score >= 65 ? "Needs attention" : "Action needed";
    const parts = [];
    if (crit) parts.push(`${crit} critical`);
    if (warn) parts.push(`${warn} warning${warn > 1 ? "s" : ""}`);
    document.getElementById("health-meta").textContent = `${state.site}${isLive() ? "" : ", as of " + fmtDate(state.range.to, true)}: ${parts.length ? parts.join(", ") : "no issues found"}`;
  }

  function renderBanner() {
    const banner = document.getElementById("missing-banner");
    const txt = document.getElementById("missing-text");
    if (state.logsError || !isLive()) { banner.classList.remove("show"); return; }
    const rows = state.rows;
    const yesterday = addDays(todayStr(), -1);
    if (!rows.length) {
      txt.innerHTML = `<strong>No readings for ${escapeHtml(state.site)} yet.</strong> Log yesterday's meters to start tracking.`;
      banner.classList.add("show");
      return;
    }
    const last = rows[rows.length - 1].date;
    if (last < yesterday) {
      txt.innerHTML = `<strong>${escapeHtml(state.site)} readings for ${fmtDate(yesterday, true)} haven't been logged.</strong> Last logged day: ${fmtDate(last, true)}.`;
      banner.classList.add("show");
    } else {
      banner.classList.remove("show");
    }
  }

  function renderAll() {
    state.rows = buildRows();
    renderRangeBar();
    renderSolar();
    renderWater();
    renderInsights();
    renderBanner();
  }

  /* ------------------------------------------------------------------
   * Log readings modal
   * ------------------------------------------------------------------ */
  const form = document.getElementById("log-form");
  const NUM_FIELDS = ["borehole_meter", "smart_meter", "permeate_m3", "reject_m3", "units_sold", "rw_tank_level", "tw_tank_level"];

  function openModal(id) {
    const m = document.getElementById(id);
    m.classList.add("show");
    const first = m.querySelector("input:not([disabled]), select:not([disabled])");
    if (first) setTimeout(() => first.focus(), 30);
  }
  function closeModal(m) { m.classList.remove("show"); }
  document.querySelectorAll(".modal").forEach(m => {
    m.addEventListener("click", e => { if (e.target === m || e.target.closest("[data-close]")) closeModal(m); });
  });
  document.addEventListener("keydown", e => { if (e.key === "Escape") document.querySelectorAll(".modal.show").forEach(closeModal); });

  function openLogModal(date) {
    const d = date || addDays(todayStr(), -1);
    form.reset();
    form.site.value = state.site;
    form.site.disabled = true;
    form.log_date.value = d;
    form.log_date.max = todayStr();
    resetDeleteButton();
    applySiteFields();
    openModal("log-modal");
    loadDayIntoForm(d);
  }
  function applySiteFields() {
    const cfg = SITE_CONFIG[state.site];
    ["permeate_m3", "reject_m3"].forEach(f => { form[f].closest(".field").style.display = cfg.hasRO ? "" : "none"; });
    form.smart_meter.closest(".field").style.display = cfg.hasSmartMeter ? "" : "none";
  }

  // Finds the saved log for a day: from what's loaded, otherwise from the server
  // (so days older than the loaded window can be edited too).
  async function findLog(date) {
    const local = state.logs.find(l => String(l.log_date).slice(0, 10) === date);
    if (local) return local;
    try {
      const found = await api("frappe.client.get_list", {
        doctype: LOG_DOCTYPE, fields: LOG_FIELDS,
        filters: [["site", "=", state.site], ["log_date", "=", date]], limit_page_length: 1
      });
      return (found && found[0]) || null;
    } catch (e) {
      return null;
    }
  }

  async function loadDayIntoForm(date) {
    state.loadingDay = true;
    state.editingDoc = null;
    state.editingName = null;
    document.getElementById("log-meta").textContent = "Checking for saved readings…";
    updatePreview();
    const existing = await findLog(date);
    if (form.log_date.value !== date) return; // user picked another date meanwhile
    state.loadingDay = false;
    state.editingDoc = existing;
    state.editingName = existing ? existing.name : null;
    NUM_FIELDS.forEach(f => { form[f].value = existing && existing[f] != null ? existing[f] : ""; });
    form.notes.value = existing && existing.notes ? existing.notes : "";

    const title = document.getElementById("log-modal-title");
    const pill = document.getElementById("log-mode");
    const meta = document.getElementById("log-meta");
    if (existing) {
      title.textContent = `Edit readings for ${fmtDate(date, true)}`;
      pill.textContent = "Editing saved day"; pill.classList.add("edit");
      meta.textContent = existing.modified
        ? `Last updated ${prettyDate(existing.modified)}${existing.modified_by ? " by " + existing.modified_by : ""}. Clear a field to remove that reading.`
        : "Clear a field to remove that reading.";
      document.getElementById("delete-log-btn").hidden = false;
    } else {
      title.textContent = `Log readings for ${fmtDate(date, true)}`;
      pill.textContent = "New day"; pill.classList.remove("edit");
      meta.textContent = "";
      document.getElementById("delete-log-btn").hidden = true;
    }
    resetDeleteButton();
    updatePreview();
  }

  function shown(v, field) {
    if (v == null || v === "") return "empty";
    return field === "notes" ? (String(v).length > 40 ? String(v).slice(0, 40) + "…" : String(v)) : format(v, 2);
  }
  function diffAgainstSaved(values) {
    const saved = state.editingDoc;
    if (!saved) return [];
    const out = [];
    NUM_FIELDS.forEach(f => {
      const a = num(saved[f]), b = values[f];
      const same = a == null && b == null || (a != null && b != null && Math.abs(a - b) < 1e-9);
      if (!same) out.push({ field: f, label: FIELD_LABELS[f], from: shown(a, f), to: shown(b, f) });
    });
    const na = (saved.notes || "").trim(), nb = (form.notes.value || "").trim();
    if (na !== nb) out.push({ field: "notes", label: FIELD_LABELS.notes, from: shown(na, "notes"), to: shown(nb, "notes") });
    return out;
  }

  function neighbours(date, field) {
    const sorted = state.logs.filter(l => num(l[field]) != null).sort((a, b) => String(a.log_date).localeCompare(String(b.log_date)));
    let prev = null, next = null;
    sorted.forEach(l => {
      const d = String(l.log_date).slice(0, 10);
      if (d < date) prev = l;
      if (d > date && !next) next = l;
    });
    return { prev, next };
  }

  function updatePreview() {
    const s = state.settings, cfg = SITE_CONFIG[state.site];
    const date = form.log_date.value;
    const v = {}; NUM_FIELDS.forEach(f => { v[f] = num(form[f].value); });
    const warns = [], errors = [];
    const items = [];

    const meter = (field, hintId, label) => {
      const { prev, next } = neighbours(date, field);
      const hint = document.getElementById(hintId);
      if (hint) hint.textContent = prev ? `Last reading ${format(prev[field], 2)} on ${fmtDate(prev.log_date)}` : "First reading for this meter";
      let perDay = null;
      if (v[field] != null && prev) {
        const gap = dayDiff(String(prev.log_date).slice(0, 10), date);
        if (v[field] < num(prev[field])) errors.push(`${label} is lower than the previous reading (${format(prev[field], 2)}). Meters only count up.`);
        else if (gap > 0) perDay = (v[field] - num(prev[field])) / gap;
        if (gap > 1) warns.push(`${label}: ${gap} days since the last reading, so the volume is averaged per day.`);
      }
      if (v[field] != null && next && v[field] > num(next[field])) errors.push(`${label} is higher than the reading logged on ${fmtDate(next.log_date)} (${format(next[field], 2)}).`);
      return perDay;
    };

    const pumped = meter("borehole_meter", "f-bh-hint", "Borehole meter");
    const pumpedSmart = cfg.hasSmartMeter ? meter("smart_meter", "f-sm-hint", "Smart meter") : null;
    items.push(["Pumped (borehole)", pumped, 1, " m³"]);

    if (pumped != null) {
      const hist = state.rows.map(r => r.pumped).filter(x => x != null).slice(-30);
      const m = mean(hist), sd = stdev(hist);
      if (sd && Math.abs(pumped - m) > 3 * sd) warns.push(`Pumped volume of ${format(pumped, 0)} m³ is far from the usual ${format(m, 0)} m³. Double-check the borehole reading.`);
    }
    if (cfg.hasSmartMeter) {
      items.push(["Pumped (smart)", pumpedSmart, 1, " m³"]);
      if (pumped > 0 && pumpedSmart != null) {
        const dev = (pumpedSmart - pumped) / pumped * 100;
        items.push(["Meter deviation", dev, 1, "%"]);
        if (Math.abs(dev - s.devExpected) > s.devTolerance) warns.push(`Meter deviation ${format(dev, 1)}% is outside the usual ${format(s.devExpected - s.devTolerance, 1)}–${format(s.devExpected + s.devTolerance, 1)}% band.`);
      }
    }
    if (cfg.hasRO) {
      if (v.permeate_m3 != null && v.reject_m3 != null && v.permeate_m3 + v.reject_m3 > 0) {
        const rec = v.permeate_m3 / (v.permeate_m3 + v.reject_m3) * 100;
        items.push(["RO recovery", rec, 1, "%"]);
        if (rec < 40 || rec > 90) warns.push(`Recovery of ${format(rec, 1)}% is outside what this plant normally achieves; check the permeate and reject figures.`);
        if (pumped != null && v.permeate_m3 + v.reject_m3 > pumped * 1.3) warns.push("The RO treated much more than the borehole delivered. Fine if the raw-water tank was drawn down; otherwise re-check.");
      }
    }
    const supplied = cfg.hasRO ? v.permeate_m3 : pumped;
    if (supplied > 0 && v.units_sold != null) {
      items.push(["Non-revenue water", (supplied - v.units_sold) / supplied * 100, 1, "%"]);
      if (v.units_sold > supplied * 1.05) warns.push(`Units sold exceed the water ${cfg.hasRO ? "sent to the estate" : "pumped"}. Check whether the sales figure covers a different period.`);
    }
    ["rw_tank_level", "tw_tank_level"].forEach(f => { if (v[f] != null && (v[f] < 0 || v[f] > 100)) errors.push("Tank levels must be between 0 and 100%."); });
    if (date > todayStr()) errors.push("The date can't be in the future.");
    if (!NUM_FIELDS.some(f => v[f] != null)) errors.push("Enter at least one reading.");

    document.getElementById("preview-grid").innerHTML = items.map(([l, val, d, u]) =>
      `<div class="preview__item"><span>${l}</span><b>${val == null ? "—" : format(val, d) + u}</b></div>`).join("");
    document.getElementById("preview-warn").innerHTML =
      errors.map(e => `<li class="err">${escapeHtml(e)}</li>`).join("") + warns.map(w => `<li>${escapeHtml(w)}</li>`).join("");
    const changes = diffAgainstSaved(v);
    document.getElementById("preview-changes").innerHTML = state.editingDoc && changes.length
      ? `<li><b>${changes.length} change${changes.length > 1 ? "s" : ""} to save</b></li>` + changes.map(c =>
          `<li>${escapeHtml(c.label)}: <s>${escapeHtml(c.from)}</s> → <b>${escapeHtml(c.to)}</b></li>`).join("")
      : "";
    NUM_FIELDS.concat("notes").forEach(f => form[f].classList.toggle("changed", !!state.editingDoc && changes.some(c => c.field === f)));
    const saveBtn = document.getElementById("save-log-btn");
    const nothingChanged = !!state.editingDoc && changes.length === 0;
    saveBtn.disabled = errors.length > 0 || nothingChanged || state.loadingDay;
    saveBtn.textContent = state.editingDoc ? (nothingChanged ? "No changes" : "Save changes") : "Save readings";
    return { values: v, errors, changes };
  }

  form.addEventListener("input", e => {
    if (e.target.name === "log_date") { loadDayIntoForm(form.log_date.value); return; }
    updatePreview();
  });

  function isMissingEndpoint(e) {
    return e.status === 404 || /has no attribute|not found|No module|is not whitelisted/i.test(e.message);
  }

  async function saveLog() {
    const { values, errors } = updatePreview();
    if (errors.length) return;
    const btn = document.getElementById("save-log-btn");
    btn.disabled = true;
    const editing = state.editingDoc;
    const doc = Object.assign({ site: state.site, log_date: form.log_date.value, notes: form.notes.value || null }, values);
    if (editing && editing.modified) doc.expected_modified = editing.modified;
    try {
      let saved = null;
      try {
        saved = await api(`${API}.save_ro_log`, { data: JSON.stringify(doc) });
      } catch (e) {
        if (!isMissingEndpoint(e)) throw e;
        const { site, log_date, expected_modified, ...fields } = doc;
        if (editing) {
          // Without the API, check for a concurrent edit before overwriting.
          const fresh = await api("frappe.client.get_value", { doctype: LOG_DOCTYPE, filters: editing.name, fieldname: "modified" });
          if (fresh && expected_modified && fresh.modified !== expected_modified) {
            throw new Error("Someone else changed this day after you opened it. Close and reopen the day to see their values.");
          }
          saved = await api("frappe.client.set_value", { doctype: LOG_DOCTYPE, name: editing.name, fieldname: fields });
        } else {
          saved = await api("frappe.client.insert", { doc: Object.assign({ doctype: LOG_DOCTYPE, site, log_date }, fields) });
        }
      }
      state.highlightName = (saved && saved.name) || (editing && editing.name) || null;
      closeModal(document.getElementById("log-modal"));
      toast(editing ? `Changes saved for ${fmtDate(doc.log_date)}` : `Readings saved for ${fmtDate(doc.log_date)}`);
      await loadWater();
      renderAll();
    } catch (e) {
      document.getElementById("preview-warn").insertAdjacentHTML("afterbegin", `<li class="err">Not saved: ${escapeHtml(e.message)}</li>`);
      btn.disabled = false;
    }
  }

  // Two-step delete: first click arms the button, second click deletes.
  function resetDeleteButton() {
    const b = document.getElementById("delete-log-btn");
    b.classList.remove("confirm");
    b.textContent = "Delete day";
    clearTimeout(resetDeleteButton._t);
  }
  async function deleteLog() {
    const b = document.getElementById("delete-log-btn");
    const editing = state.editingDoc;
    if (!editing) return;
    if (!b.classList.contains("confirm")) {
      b.classList.add("confirm");
      b.textContent = "Click again to delete";
      resetDeleteButton._t = setTimeout(resetDeleteButton, 4000);
      return;
    }
    b.disabled = true;
    try {
      await api("frappe.client.delete", { doctype: LOG_DOCTYPE, name: editing.name });
      closeModal(document.getElementById("log-modal"));
      toast(`Readings for ${fmtDate(editing.log_date)} deleted`);
      await loadWater();
      renderAll();
    } catch (e) {
      document.getElementById("preview-warn").insertAdjacentHTML("afterbegin", `<li class="err">Not deleted: ${escapeHtml(e.message)}</li>`);
    } finally {
      b.disabled = false;
      resetDeleteButton();
    }
  }

  /* ------------------------------------------------------------------
   * Settings modal
   * ------------------------------------------------------------------ */
  const sForm = document.getElementById("settings-form");
  function openSettings() {
    Object.keys(DEFAULT_SETTINGS).forEach(k => { if (sForm[k]) sForm[k].value = state.settings[k]; });
    openModal("settings-modal");
  }
  document.getElementById("settings-save").addEventListener("click", () => {
    Object.keys(DEFAULT_SETTINGS).forEach(k => { const v = num(sForm[k] && sForm[k].value); if (v != null) state.settings[k] = v; });
    storageSet("ro_dash_settings", JSON.stringify(state.settings));
    closeModal(document.getElementById("settings-modal"));
    toast("Settings saved");
    renderAll();
  });
  document.getElementById("settings-reset").addEventListener("click", () => {
    state.settings = Object.assign({}, DEFAULT_SETTINGS);
    storageSet("ro_dash_settings", JSON.stringify(state.settings));
    Object.keys(DEFAULT_SETTINGS).forEach(k => { if (sForm[k]) sForm[k].value = state.settings[k]; });
    renderAll();
  });

  /* ------------------------------------------------------------------
   * AI daily summary (existing)
   * ------------------------------------------------------------------ */
  async function loadDailySummary() {
    const el = document.getElementById("daily-summary");
    if (!el) return;
    try {
      const row = await api("upande_goodwe.goodwe.intelligency.get_latest_daily_summary", {});
      if (row && row.summary_text) {
        let d = row.summary_date;
        try { if (frappe.datetime && frappe.datetime.str_to_user) d = frappe.datetime.str_to_user(row.summary_date); } catch (e) { /* ignore */ }
        el.textContent = `${d}: ${row.summary_text}`;
        el.style.display = "block";
      } else {
        el.style.display = "none";
      }
    } catch (error) {
      el.style.display = "none";
    }
  }

  /* ------------------------------------------------------------------
   * Wiring
   * ------------------------------------------------------------------ */
  function setSiteButtons() {
    document.querySelectorAll("#site-switch button").forEach(b => b.classList.toggle("on", b.dataset.site === state.site));
  }
  document.querySelectorAll("#site-switch button").forEach(b => {
    b.addEventListener("click", async () => {
      if (b.dataset.site === state.site) return;
      state.site = b.dataset.site;
      storageSet("ro_dash_site", state.site);
      setSiteButtons();
      await loadWater();
      renderAll();
    });
  });
  document.getElementById("log-btn").addEventListener("click", () => openLogModal());
  document.getElementById("banner-log-btn").addEventListener("click", () => openLogModal());
  document.getElementById("save-log-btn").addEventListener("click", saveLog);
  document.getElementById("delete-log-btn").addEventListener("click", deleteLog);
  const findDate = document.getElementById("find-date");
  findDate.max = todayStr();
  findDate.value = addDays(todayStr(), -1);
  document.getElementById("find-date-btn").addEventListener("click", () => { if (findDate.value) openLogModal(findDate.value); });
  findDate.addEventListener("keydown", e => { if (e.key === "Enter" && findDate.value) openLogModal(findDate.value); });
  document.getElementById("toggle-rows").addEventListener("click", () => { state.showAllRows = !state.showAllRows; renderTable(inRange(state.rows)); });
  document.getElementById("settings-btn").addEventListener("click", openSettings);
  document.getElementById("refresh-btn").addEventListener("click", refreshAll);
  document.getElementById("backfill-btn").addEventListener("click", runBackfill);

  async function refreshAll() {
    await Promise.allSettled([loadSolar(), loadWater()]);
    renderAll();
    loadMissingDays();
  }

  /* ------------------------------------------------------------------
   * Period filter
   * ------------------------------------------------------------------ */
  const rangeFrom = document.getElementById("range-from");
  const rangeTo = document.getElementById("range-to");

  function renderRangeBar() {
    const r = state.range, t = todayStr();
    document.querySelectorAll("#rangebar [data-preset]").forEach(b => b.classList.toggle("on", b.dataset.preset === r.preset));
    rangeFrom.value = r.from; rangeTo.value = r.to;
    rangeFrom.max = t; rangeTo.max = t;
    const single = r.preset === "day";
    document.getElementById("range-to-wrap").style.display = single ? "none" : "";
    document.getElementById("range-from-label").firstChild.textContent = single ? "Date " : "From ";
    document.getElementById("range-next").disabled = r.to >= t;
    const len = rangeDays(r);
    document.getElementById("range-label").innerHTML =
      `${escapeHtml(rangeText(r))}<small>${len === 1 ? "Single day" : len + " days"}${isLive() ? "" : ", past period"}</small>`;
  }

  async function setRange(range, opts) {
    let { from, to } = range;
    const t = todayStr();
    if (!validDate(from) || !validDate(to)) return;
    if (from > to) [from, to] = [to, from];
    if (to > t) to = t;
    if (from > t) from = t;
    state.range = { preset: range.preset || "custom", from, to };
    if (state.range.preset !== "custom" && state.range.preset !== "day") storageSet("ro_dash_preset", state.range.preset);
    state.showAllRows = false;
    try {
      const url = new URL(window.location.href);
      url.searchParams.set("from", from); url.searchParams.set("to", to);
      window.history.replaceState(null, "", url.toString());
    } catch (e) { /* ignore */ }
    renderRangeBar();
    document.getElementById("last-sync").textContent = "Loading…";
    if (!(opts && opts.skipLoad)) await refreshAll();
  }

  document.querySelectorAll("#rangebar [data-preset]").forEach(b => {
    b.addEventListener("click", () => {
      const p = b.dataset.preset;
      // "Single day" keeps the current end date as the day to look at.
      setRange(p === "day" ? presetRange("day", state.range.to) : presetRange(p));
    });
  });
  rangeFrom.addEventListener("change", () => {
    if (!validDate(rangeFrom.value)) return;
    if (state.range.preset === "day") setRange({ preset: "day", from: rangeFrom.value, to: rangeFrom.value });
    else setRange({ preset: "custom", from: rangeFrom.value, to: rangeFrom.value > state.range.to ? rangeFrom.value : state.range.to });
  });
  rangeTo.addEventListener("change", () => {
    if (!validDate(rangeTo.value)) return;
    setRange({ preset: "custom", from: rangeTo.value < state.range.from ? rangeTo.value : state.range.from, to: rangeTo.value });
  });
  // Step to the previous / next period of the same length (whole months for month presets).
  function stepRange(dir) {
    const r = state.range;
    if (r.preset === "mtd" || r.preset === "lastmonth") {
      const anchor = dir < 0 ? addDays(r.from, -1) : addDays(r.from.slice(0, 7) + "-28", 7);
      const first = anchor.slice(0, 7) + "-01";
      const last = addDays(addDays(first.slice(0, 7) + "-28", 7).slice(0, 7) + "-01", -1);
      return setRange({ preset: "custom", from: first, to: last });
    }
    const len = rangeDays(r);
    const from = addDays(r.from, dir * len), to = addDays(r.to, dir * len);
    setRange({ preset: len === 1 ? "day" : "custom", from, to });
  }
  document.getElementById("range-prev").addEventListener("click", () => stepRange(-1));
  document.getElementById("range-next").addEventListener("click", () => stepRange(1));

  setSiteButtons();
  setRange(state.range, { skipLoad: true });
  refreshAll();
  loadDailySummary();
  // Only periods that include today or yesterday need polling.
  setInterval(async () => { if (isLive()) { await loadSolar(); renderAll(); } }, SOLAR_REFRESH_MS);
  setInterval(async () => { if (isLive()) { await loadWater(); renderAll(); } }, WATER_REFRESH_MS);
});

