{% set active_page = 'monitors' %}
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Solar &amp; Water Plant - Upande Universal Dashboard</title>

  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Poppins:wght@400;500;600&display=swap" rel="stylesheet">
  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>

  <style>
    :root {
      --ink: #0a0a0a;
      --ink-1: #1a1a18;
      --ink-2: #2a2a26;
      --ink-3: #3a3a34;
      --ink-4: #5a5a52;
      --ink-mute: #8a8780;
      --ink-faint: #b8b6ae;

      --bg: #f4f3ef;
      --surface: #fafaf6;
      --surface-2: #ffffff;
      --hairline: rgba(10, 10, 10, 0.06);
      --hairline-2: rgba(10, 10, 10, 0.12);
      --shadow-card: 0 1px 0 rgba(10, 10, 10, 0.04), 0 8px 32px -16px rgba(10, 10, 10, 0.10);
      --shadow-hover: 0 1px 0 rgba(10, 10, 10, 0.06), 0 24px 48px -24px rgba(10, 10, 10, 0.18);

      --signal: #228883;
      --water: #2b6f9e;
      --water-soft: rgba(43, 111, 158, 0.12);
      --solar: #7aa23f;
      --crit: #c4302b;
      --crit-soft: rgba(196, 48, 43, 0.08);
      --warn: #c98418;
      --warn-soft: rgba(217, 150, 46, 0.10);
      --good: #5f8a2c;
      --good-soft: rgba(122, 162, 63, 0.10);
      --info-soft: rgba(34, 136, 131, 0.08);

      --grad-ink: linear-gradient(135deg, #0a0a0a 0%, #3a3a34 100%);

      --sans: 'Poppins', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --display: 'Fraunces', Georgia, serif;
    }

    * { box-sizing: border-box; }
    body { margin: 0; font-family: var(--sans); font-size: 14px; color: var(--ink-3); background: var(--bg); line-height: 1.55; -webkit-font-smoothing: antialiased; }
    a { color: inherit; text-decoration: none; }
    button, input, select, textarea { font-family: inherit; }
    :focus-visible { outline: 2px solid var(--signal); outline-offset: 2px; }

    /* Topbar */
    .topbar { background: var(--surface-2); padding: 14px 40px; display: flex; align-items: center; justify-content: space-between; position: sticky; top: 0; z-index: 10; border-bottom: 1px solid var(--hairline); }
    .topbar__brand { display: flex; align-items: center; gap: 16px; }
    .topbar__logo { height: 34px; width: auto; display: block; }
    .topbar__divider { width: 1px; height: 22px; background: var(--hairline); }
    .topbar__product { font: 600 14px var(--sans); color: var(--ink); letter-spacing: -.2px; }
    .topbar__product small { display: block; font: 500 10px var(--sans); text-transform: uppercase; letter-spacing: 1.6px; color: var(--ink-mute); margin-top: 1px; }
    .topbar__nav { display: flex; gap: 4px; margin-left: 32px; }
    .topbar__nav a { padding: 8px 14px; font: 500 13px var(--sans); color: var(--ink-4); border-radius: 999px; transition: all .2s; }
    .topbar__nav a:hover { background: rgba(10, 10, 10, 0.04); color: var(--ink); }
    .topbar__nav a.on { background: var(--ink); color: #fafaf6; }
    .topbar__right { display: flex; align-items: center; gap: 14px; font-size: 13px; color: var(--ink-4); margin-left: auto; }
    .avatar { width: 32px; height: 32px; border-radius: 50%; background: var(--grad-ink); color: #fafaf6; display: grid; place-items: center; font-weight: 600; font-size: 12px; }

    /* Page */
    .page { max-width: 1480px; margin: 0 auto; padding: 48px 40px 80px; }
    .pagehead { display: grid; grid-template-columns: 1fr auto; align-items: end; gap: 32px; margin-bottom: 28px; }
    .pagehead__eyebrow { font: 500 11px var(--sans); text-transform: uppercase; letter-spacing: 2.2px; color: var(--ink-mute); margin-bottom: 10px; display: inline-flex; align-items: center; gap: 10px; }
    .pagehead__eyebrow::before { content: ""; width: 18px; height: 1px; background: var(--ink-3); }
    .pagehead__title { font: 600 44px/1.05 var(--sans); color: var(--ink); letter-spacing: -1.3px; margin: 0; }
    .pagehead__sub { margin-top: 8px; font-size: 15px; color: var(--ink-4); margin-bottom: 0; }
    .pagehead__tools { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
    .pagehead__ai-summary { margin-top: 12px; font: 500 13px var(--sans); color: var(--ink-3); background: var(--info-soft); border-left: 3px solid var(--signal); padding: 10px 14px; border-radius: 8px; max-width: 900px; }

    .datepill { display: inline-flex; align-items: center; gap: 8px; background: var(--surface-2); border-radius: 999px; padding: 10px 16px; font: 500 12px var(--sans); color: var(--ink); box-shadow: var(--shadow-card); }
    .iconbtn { width: 40px; height: 40px; border: 0; background: var(--surface-2); border-radius: 50%; display: grid; place-items: center; cursor: pointer; color: var(--ink-4); box-shadow: var(--shadow-card); transition: all .2s; font-size: 16px; }
    .iconbtn:hover { color: var(--ink); transform: translateY(-1px); }
    .btn { border: 0; border-radius: 999px; padding: 10px 18px; font: 500 13px var(--sans); cursor: pointer; transition: all .2s; display: inline-flex; align-items: center; gap: 8px; }
    .btn--primary { background: var(--grad-ink); color: #fafaf6; box-shadow: 0 4px 14px rgba(10, 10, 10, 0.20); }
    .btn--primary:hover { transform: translateY(-1px); }
    .btn--ghost { background: var(--surface-2); color: var(--ink); box-shadow: var(--shadow-card); }
    .btn--link { background: none; padding: 0; color: var(--signal); font-weight: 600; }
    .btn:disabled { opacity: .5; cursor: not-allowed; transform: none; }

    .siteswitch { display: inline-flex; background: rgba(10, 10, 10, 0.05); padding: 4px; border-radius: 999px; }
    .siteswitch button { border: 0; background: transparent; padding: 7px 14px; border-radius: 999px; font: 500 12px var(--sans); color: var(--ink-4); cursor: pointer; }
    .siteswitch button.on { background: var(--surface-2); color: var(--ink); box-shadow: var(--shadow-card); }

    /* Tabs */
    .tabs { display: inline-flex; gap: 4px; margin-bottom: 28px; background: rgba(10, 10, 10, 0.04); padding: 5px; border-radius: 999px; max-width: 100%; overflow-x: auto; }
    .tab { background: transparent; border: 0; font: 500 13px var(--sans); color: var(--ink-4); padding: 10px 18px; border-radius: 999px; cursor: pointer; display: inline-flex; align-items: center; gap: 8px; white-space: nowrap; transition: all .2s; text-decoration: none; }
    .tab svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
    .tab:hover { color: var(--ink); }
    .tab.on { background: var(--grad-ink); color: #fafaf6; box-shadow: 0 4px 14px rgba(10, 10, 10, 0.20); }

    /* Period filter */
    .rangebar { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 16px; background: var(--surface-2); border-radius: 20px; padding: 12px 14px; box-shadow: var(--shadow-card); margin-bottom: 22px; }
    .rangebar__presets { display: inline-flex; flex-wrap: wrap; gap: 4px; background: rgba(10, 10, 10, 0.04); padding: 4px; border-radius: 999px; }
    .rangebar__presets button { border: 0; background: transparent; padding: 7px 13px; border-radius: 999px; font: 500 12px var(--sans); color: var(--ink-4); cursor: pointer; white-space: nowrap; }
    .rangebar__presets button:hover { color: var(--ink); }
    .rangebar__presets button.on { background: var(--ink); color: #fafaf6; }
    .rangebar__custom { display: inline-flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .rangebar__custom label { display: inline-flex; align-items: center; gap: 6px; font: 500 12px var(--sans); color: var(--ink-4); }
    .rangebar__custom input { border: 1px solid var(--hairline-2); background: var(--surface); border-radius: 999px; padding: 7px 12px; font-size: 13px; color: var(--ink); }
    .rangebar__custom input:focus { outline: none; border-color: var(--signal); box-shadow: 0 0 0 3px var(--info-soft); }
    .rangebar__step { width: 34px; height: 34px; border: 1px solid var(--hairline-2); background: var(--surface-2); border-radius: 50%; cursor: pointer; color: var(--ink-3); font-size: 16px; line-height: 1; }
    .rangebar__step:hover:not(:disabled) { border-color: var(--ink-3); color: var(--ink); }
    .rangebar__step:disabled { opacity: .35; cursor: not-allowed; }
    .rangebar__label { margin-left: auto; font: 500 12.5px var(--sans); color: var(--ink-3); text-align: right; }
    .rangebar__label small { display: block; color: var(--ink-mute); font-weight: 400; }
    .pill-hist { display: inline-block; margin-left: 8px; padding: 2px 9px; border-radius: 999px; background: var(--warn-soft); color: var(--warn); font: 500 11px var(--sans); vertical-align: middle; }

    /* Missing-readings banner */
    .banner { display: none; align-items: center; justify-content: space-between; gap: 16px; background: var(--warn-soft); border: 1px solid rgba(201, 132, 24, 0.25); border-radius: 16px; padding: 14px 20px; margin-bottom: 22px; color: var(--ink-2); }
    .banner.show { display: flex; }
    .banner strong { color: var(--ink); }

    /* Section heading */
    .section-title { display: flex; align-items: baseline; justify-content: space-between; margin: 36px 0 16px; gap: 16px; }
    .section-title h2 { margin: 0; font: 600 22px var(--sans); color: var(--ink); letter-spacing: -.5px; }
    .section-title span { font: 500 12px var(--sans); color: var(--ink-mute); }
    .section-title__tools { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; justify-content: flex-end; }
    .section-title__tools .btn { padding: 8px 14px; font-size: 12px; }

    /* Insights */
    .insights { display: grid; grid-template-columns: 280px 1fr; gap: 18px; margin-bottom: 18px; }
    .health { background: var(--surface-2); border-radius: 24px; padding: 28px; box-shadow: var(--shadow-card); display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
    .health__ring { position: relative; width: 168px; height: 168px; }
    .health__ring svg { width: 100%; height: 100%; transform: rotate(-90deg); }
    .health__ring circle { fill: none; stroke-width: 12; }
    .health__ring .track { stroke: rgba(10, 10, 10, 0.06); }
    .health__ring .bar { stroke: var(--signal); stroke-linecap: round; transition: stroke-dashoffset .8s ease, stroke .3s; }
    .health__score { position: absolute; inset: 0; display: grid; place-items: center; font: 600 46px/1 var(--display); color: var(--ink); letter-spacing: -1px; }
    .health__label { margin-top: 14px; font: 600 15px var(--sans); color: var(--ink); }
    .health__meta { font-size: 12px; color: var(--ink-mute); margin-top: 4px; }

    .insight-list { background: var(--surface-2); border-radius: 24px; padding: 10px 8px; box-shadow: var(--shadow-card); max-height: 460px; overflow-y: auto; }
    .insight { display: grid; grid-template-columns: 10px 1fr auto; gap: 16px; padding: 16px 20px; border-radius: 16px; align-items: start; }
    .insight + .insight { border-top: 1px solid var(--hairline); border-radius: 0; }
    .insight__dot { width: 10px; height: 10px; border-radius: 50%; margin-top: 6px; }
    .insight--critical .insight__dot { background: var(--crit); box-shadow: 0 0 0 4px var(--crit-soft); }
    .insight--warning .insight__dot { background: var(--warn); box-shadow: 0 0 0 4px var(--warn-soft); }
    .insight--good .insight__dot { background: var(--good); box-shadow: 0 0 0 4px var(--good-soft); }
    .insight--info .insight__dot { background: var(--signal); box-shadow: 0 0 0 4px var(--info-soft); }
    .insight__title { font: 600 14px var(--sans); color: var(--ink); margin: 0 0 3px; }
    .insight__body { margin: 0; font-size: 13px; color: var(--ink-4); max-width: 78ch; }
    .insight__action { margin: 6px 0 0; font-size: 12.5px; color: var(--ink-3); }
    .insight__action b { font-weight: 600; color: var(--ink-2); }
    .insight__tag { font: 500 11px var(--sans); color: var(--ink-mute); white-space: nowrap; padding-top: 2px; }

    /* KPI cards */
    .kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 18px; margin-bottom: 18px; }
    .kpi { background: var(--surface-2); border-radius: 20px; padding: 24px 26px; box-shadow: var(--shadow-card); position: relative; overflow: hidden; }
    .kpi__label { font: 500 11px var(--sans); text-transform: uppercase; letter-spacing: 1.8px; color: var(--ink-mute); margin-bottom: 12px; }
    .kpi__value { font: 600 38px/1 var(--sans); color: var(--ink); letter-spacing: -1.2px; font-feature-settings: "tnum"; display: inline-block; }
    .kpi__unit { font: 400 14px var(--sans); color: var(--ink-mute); margin-left: 4px; display: inline-block; }
    .kpi__delta { margin-top: 10px; font: 500 12px var(--sans); color: var(--ink-mute); min-height: 18px; }
    .kpi__delta.up { color: var(--good); }
    .kpi__delta.down { color: var(--crit); }
    .kpi__delta.flat { color: var(--ink-mute); }
    .kpi--water::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--water); }
    .kpi--flag-warning::before { background: var(--warn); }
    .kpi--flag-critical::before { background: var(--crit); }

    /* Cards & charts */
    .card { background: var(--surface-2); border-radius: 24px; padding: 28px 32px; box-shadow: var(--shadow-card); margin-bottom: 18px; }
    .card__head { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 20px; gap: 24px; }
    .card__head h3 { margin: 0; font: 600 18px var(--sans); color: var(--ink); letter-spacing: -.4px; }
    .card__head .meta { font: 500 12px var(--sans); color: var(--ink-mute); text-align: right; }
    .card__note { margin: 14px 0 0; font-size: 12.5px; color: var(--ink-4); }
    .row-2-eq { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-bottom: 18px; }
    .row-2-eq > .card { margin-bottom: 0; }
    .chart-container { position: relative; height: 260px; width: 100%; }
    .chart-container-full { position: relative; height: 300px; width: 100%; }
    .empty { display: none; position: absolute; inset: 0; place-items: center; text-align: center; color: var(--ink-mute); font-size: 13px; padding: 20px; }
    .empty.show { display: grid; }

    /* Table */
    .table-wrap { overflow-x: auto; }
    table.logs { width: 100%; border-collapse: collapse; font-size: 13px; font-feature-settings: "tnum"; }
    table.logs th { text-align: right; font: 500 11px var(--sans); color: var(--ink-mute); padding: 10px 12px; border-bottom: 1px solid var(--hairline-2); white-space: nowrap; }
    table.logs td { text-align: right; padding: 11px 12px; border-bottom: 1px solid var(--hairline); white-space: nowrap; color: var(--ink-2); }
    table.logs th:first-child, table.logs td:first-child { text-align: left; }
    table.logs tbody tr { cursor: pointer; }
    table.logs tbody tr:hover { background: rgba(10, 10, 10, 0.025); }
    td.flag-warning { color: var(--warn); font-weight: 600; }
    td.flag-critical { color: var(--crit); font-weight: 600; }
    td.muted { color: var(--ink-faint); }

    /* Modal */
    .modal { position: fixed; inset: 0; background: rgba(10, 10, 10, 0.35); display: none; align-items: flex-start; justify-content: center; z-index: 50; padding: 40px 16px; overflow-y: auto; }
    .modal.show { display: flex; }
    .modal__panel { background: var(--surface-2); border-radius: 24px; width: 100%; max-width: 760px; padding: 30px 32px; box-shadow: 0 40px 80px -30px rgba(10, 10, 10, 0.4); }
    .modal__head { display: flex; justify-content: space-between; align-items: start; gap: 16px; margin-bottom: 6px; }
    .modal__head h3 { margin: 0; font: 600 20px var(--sans); color: var(--ink); letter-spacing: -.4px; }
    .modal__sub { margin: 0 0 22px; font-size: 13px; color: var(--ink-4); }
    .form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px 18px; }
    .form-grid .full { grid-column: 1 / -1; }
    .fieldset-title { grid-column: 1 / -1; font: 600 13px var(--sans); color: var(--ink); margin: 10px 0 -4px; padding-top: 14px; border-top: 1px solid var(--hairline); }
    .fieldset-title:first-child { border-top: 0; padding-top: 0; margin-top: 0; }
    .field label { display: block; font: 500 12px var(--sans); color: var(--ink-3); margin-bottom: 6px; }
    .field input, .field select, .field textarea { width: 100%; border: 1px solid var(--hairline-2); background: var(--surface); border-radius: 12px; padding: 10px 12px; font-size: 14px; color: var(--ink); }
    .field input:focus, .field select:focus, .field textarea:focus { outline: none; border-color: var(--signal); box-shadow: 0 0 0 3px var(--info-soft); }
    .field small { display: block; margin-top: 5px; font-size: 11.5px; color: var(--ink-mute); }
    .preview { margin-top: 20px; background: var(--surface); border-radius: 16px; padding: 16px 18px; font-size: 13px; }
    .preview__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
    .preview__item span { display: block; font-size: 11.5px; color: var(--ink-mute); }
    .preview__item b { font: 600 17px var(--sans); color: var(--ink); font-feature-settings: "tnum"; }
    .preview__warn { margin: 12px 0 0; padding: 0; list-style: none; }
    .preview__warn li { padding: 6px 0 0 18px; position: relative; color: var(--ink-3); }
    .preview__warn li::before { content: ""; position: absolute; left: 2px; top: 13px; width: 7px; height: 7px; border-radius: 50%; background: var(--warn); }
    .preview__warn li.err::before { background: var(--crit); }
    .modal__foot { display: flex; justify-content: flex-end; align-items: center; gap: 10px; margin-top: 22px; }
    .modal__foot .spacer { flex: 1; }
    .modal__meta { margin: -14px 0 18px; font-size: 12px; color: var(--ink-mute); min-height: 16px; }
    .mode-pill { display: inline-block; font: 500 11px var(--sans); padding: 3px 10px; border-radius: 999px; margin-left: 10px; vertical-align: middle; background: var(--info-soft); color: var(--signal); }
    .mode-pill.edit { background: var(--warn-soft); color: var(--warn); }
    .btn--danger { background: var(--crit-soft); color: var(--crit); }
    .btn--danger.confirm { background: var(--crit); color: #fff; }
    .changes { margin: 12px 0 0; padding: 10px 0 0; border-top: 1px solid var(--hairline); list-style: none; font-size: 12.5px; color: var(--ink-3); }
    .changes:empty { display: none; }
    .changes li { padding: 2px 0; font-feature-settings: "tnum"; }
    .changes s { color: var(--ink-faint); }
    .changes b { color: var(--ink); font-weight: 600; }
    .field input.changed, .field textarea.changed { border-color: var(--warn); background: #fffaf0; }
    .findday { display: flex; gap: 8px; align-items: center; }
    .findday input { border: 1px solid var(--hairline-2); background: var(--surface); border-radius: 999px; padding: 7px 12px; font-size: 13px; color: var(--ink); }
    .rowbtn { border: 1px solid var(--hairline-2); background: var(--surface-2); border-radius: 999px; padding: 4px 12px; font: 500 12px var(--sans); color: var(--ink-3); cursor: pointer; }
    .rowbtn:hover { border-color: var(--ink-3); color: var(--ink); }
    table.logs tr.row-updated td { animation: rowflash 2.4s ease; }
    @keyframes rowflash { 0%, 40% { background: var(--good-soft); } 100% { background: transparent; } }
    .table-foot { display: flex; justify-content: center; margin-top: 14px; }

    .toast { position: fixed; bottom: 28px; left: 50%; transform: translateX(-50%) translateY(20px); background: var(--ink); color: #fafaf6; padding: 12px 20px; border-radius: 999px; font: 500 13px var(--sans); opacity: 0; transition: all .25s; z-index: 60; pointer-events: none; }
    .toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

    @media (max-width: 1000px) {
      .row-2-eq, .insights { grid-template-columns: 1fr; }
      .pagehead { grid-template-columns: 1fr; }
      .pagehead__tools { justify-content: flex-start; }
      .topbar { padding: 14px 20px; }
      .topbar__nav, .topbar__right span { display: none; }
      .page { padding: 32px 20px 60px; }
      .form-grid { grid-template-columns: 1fr; }
    }
    .visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
    @media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }
  </style>
</head>
<body>

  <!-- Top Navigation Bar -->
  <div class="topbar">
    <div class="topbar__brand">
      <!-- Animated Upande / GoodWe / HydraX logo, built by upande_goodwe/goodwe/branding.py -->
      <img class="topbar__logo" alt="Upande" src="/assets/upande_goodwe/images/upande-goodwe-logo.svg" />
      <div class="topbar__divider"></div>
      <div class="topbar__product">
        Upande GoodWe
        <small>Solar &amp; water monitoring</small>
      </div>
      <nav class="topbar__nav">
        <a href="" class="on">Monitors</a>
        <a href="readings">Inverters</a>
      </nav>
    </div>
    <div class="topbar__right">
      <span>system@upande.com</span>
      <div class="avatar">GW</div>
    </div>
  </div>

  <div class="page">
    <div class="pagehead">
      <div>
        <div class="pagehead__eyebrow">Upande GoodWe Integration</div>
        <h1 class="pagehead__title">Solar &amp; Water Plant</h1>
        <p class="pagehead__sub">Borehole, RO plant and sales in one view, with solar energy from the GoodWe inverters</p>
        <p class="pagehead__ai-summary" id="daily-summary" style="display: none;"></p>
      </div>
      <div class="pagehead__tools">
        <div class="siteswitch" id="site-switch" role="group" aria-label="Site">
          <button type="button" data-site="VV" class="on">VV</button>
          <button type="button" data-site="Yamin">Yamin</button>
        </div>
        <span class="datepill" id="last-sync">Loading...</span>
        <button class="iconbtn" id="settings-btn" title="Thresholds and tariff" aria-label="Thresholds and tariff">⚙</button>
        <button class="iconbtn" id="refresh-btn" title="Refresh data" aria-label="Refresh data">↻</button>
        <button class="btn btn--primary" id="log-btn" type="button">+ Log readings</button>
      </div>
    </div>

    <div class="tabs">
      <a href="" class="tab on">
        <svg viewBox="0 0 24 24"><path d="M18 20V10M12 20V4M6 20v-6"></path></svg> Overview &amp; insights
      </a>
      <a href="readings" class="tab">
        <svg viewBox="0 0 24 24"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"></rect><line x1="8" y1="21" x2="16" y2="21"></line><line x1="12" y1="17" x2="12" y2="21"></line></svg> Inverter fleet
      </a>
    </div>

    <div class="rangebar" id="rangebar">
      <div class="rangebar__presets" role="group" aria-label="Period">
        <button type="button" data-preset="today">Today</button>
        <button type="button" data-preset="yesterday">Yesterday</button>
        <button type="button" data-preset="day">Single day</button>
        <button type="button" data-preset="7d">7 days</button>
        <button type="button" data-preset="30d">30 days</button>
        <button type="button" data-preset="90d">90 days</button>
        <button type="button" data-preset="mtd">This month</button>
        <button type="button" data-preset="lastmonth">Last month</button>
      </div>
      <div class="rangebar__custom">
        <button type="button" class="rangebar__step" id="range-prev" aria-label="Previous period">‹</button>
        <label for="range-from" id="range-from-label">From <input type="date" id="range-from"></label>
        <label for="range-to" id="range-to-wrap">To <input type="date" id="range-to"></label>
        <button type="button" class="rangebar__step" id="range-next" aria-label="Next period">›</button>
      </div>
      <div class="rangebar__label" id="range-label" aria-live="polite"></div>
    </div>

    <div class="banner" id="missing-banner">
      <div id="missing-text"></div>
      <button class="btn btn--primary" id="banner-log-btn" type="button">Log readings</button>
    </div>

    <!-- Insights -->
    <div class="insights">
      <div class="health">
        <div class="health__ring">
          <svg viewBox="0 0 168 168" aria-hidden="true">
            <circle class="track" cx="84" cy="84" r="72"></circle>
            <circle class="bar" id="health-bar" cx="84" cy="84" r="72" stroke-dasharray="452.4" stroke-dashoffset="452.4"></circle>
          </svg>
          <div class="health__score" id="health-score">—</div>
        </div>
        <div class="health__label" id="health-label">Plant health</div>
        <div class="health__meta" id="health-meta">Calculating…</div>
      </div>
      <div class="insight-list" id="insight-list" aria-live="polite">
        <div class="insight insight--info"><span class="insight__dot"></span><div><p class="insight__title">Loading insights…</p></div><span></span></div>
      </div>
    </div>

    <!-- Water & RO -->
    <div class="section-title">
      <h2>Water &amp; RO plant</h2>
      <span id="water-asof">Latest logged day</span>
    </div>

    <div class="kpi-grid">
      <div class="kpi kpi--water" id="kpi-pumped">
        <div class="kpi__label">Pumped from borehole</div>
        <div class="kpi__value" data-v>—</div><div class="kpi__unit">m³</div>
        <div class="kpi__delta" data-d></div>
      </div>
      <div class="kpi kpi--water" id="kpi-recovery">
        <div class="kpi__label">RO recovery</div>
        <div class="kpi__value" data-v>—</div><div class="kpi__unit">%</div>
        <div class="kpi__delta" data-d></div>
      </div>
      <div class="kpi kpi--water" id="kpi-sold">
        <div class="kpi__label">Units sold</div>
        <div class="kpi__value" data-v>—</div><div class="kpi__unit">m³</div>
        <div class="kpi__delta" data-d></div>
      </div>
      <div class="kpi kpi--water" id="kpi-nrw">
        <div class="kpi__label">Non-revenue water</div>
        <div class="kpi__value" data-v>—</div><div class="kpi__unit">%</div>
        <div class="kpi__delta" data-d></div>
      </div>
      <div class="kpi kpi--water" id="kpi-deviation">
        <div class="kpi__label">Meter deviation</div>
        <div class="kpi__value" data-v>—</div><div class="kpi__unit">%</div>
        <div class="kpi__delta" data-d></div>
      </div>
      <div class="kpi kpi--water" id="kpi-energy">
        <div class="kpi__label">Energy per m³</div>
        <div class="kpi__value" data-v>—</div><div class="kpi__unit">kWh</div>
        <div class="kpi__delta" data-d></div>
      </div>
    </div>

    <div class="card">
      <div class="card__head">
        <h3>Daily water balance</h3>
        <span class="meta">Where each day's pumped water went (m³)</span>
      </div>
      <div class="chart-container-full">
        <canvas id="chart-water-balance"></canvas>
        <div class="empty" id="empty-water-balance">No readings logged yet for this site. Log the first day to start the balance.</div>
      </div>
    </div>

    <div class="row-2-eq">
      <div class="card">
        <div class="card__head">
          <h3>RO recovery</h3>
          <span class="meta">Permeate ÷ (permeate + reject)</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-ro-recovery"></canvas>
          <div class="empty" id="empty-ro-recovery">Log permeate and reject volumes to track recovery.</div>
        </div>
      </div>
      <div class="card">
        <div class="card__head">
          <h3>Smart vs mechanical meter</h3>
          <span class="meta">Daily deviation with expected band</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-meter-dev"></canvas>
          <div class="empty" id="empty-meter-dev">Log both borehole and smart meter readings to compare them.</div>
        </div>
      </div>
    </div>

    <div class="row-2-eq">
      <div class="card">
        <div class="card__head">
          <h3>Demand vs solar by hour</h3>
          <span class="meta">Share of daily estate demand and solar output</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-demand-solar"></canvas>
        </div>
        <p class="card__note" id="demand-solar-note"></p>
      </div>
      <div class="card">
        <div class="card__head">
          <h3>Energy per m³ pumped</h3>
          <span class="meta">Solar kWh ÷ borehole m³</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-energy-intensity"></canvas>
          <div class="empty" id="empty-energy-intensity">Needs matching days of GoodWe energy and borehole readings.</div>
        </div>
      </div>
    </div>

    <div class="card">
      <div class="card__head">
        <div>
          <h3>Recent readings</h3>
          <span class="meta" id="table-meta">Edit a day from the table, or open any date</span>
        </div>
        <div class="findday">
          <label for="find-date" class="meta">Date</label>
          <input type="date" id="find-date">
          <button class="btn btn--ghost" type="button" id="find-date-btn">Open day</button>
        </div>
      </div>
      <div class="table-wrap">
        <table class="logs">
          <thead>
            <tr>
              <th>Date</th><th>Borehole m³</th><th>Smart m³</th><th>Deviation</th>
              <th>Permeate m³</th><th>Reject m³</th><th>Recovery</th>
              <th>Sold m³</th><th>NRW</th><th>Sold ÷ pumped</th><th>kWh/m³</th><th><span class="visually-hidden">Actions</span></th>
            </tr>
          </thead>
          <tbody id="logs-body"><tr><td colspan="12" class="muted">Loading…</td></tr></tbody>
        </table>
      </div>
      <div class="table-foot"><button class="btn btn--ghost" type="button" id="toggle-rows" hidden>Show all loaded days</button></div>
    </div>

    <!-- Solar (GoodWe API) -->
    <div class="section-title">
      <h2>Solar</h2>
      <div class="section-title__tools">
        <span id="solar-asof">Live from GoodWe, averaged across active inverters</span>
        <button class="btn btn--ghost" type="button" id="backfill-btn" hidden
                title="Fetch GoodWe's own daily totals from SEMS+ for days with no live data">Fetch missing days</button>
      </div>
    </div>

    <div class="kpi-grid">
      <div class="kpi">
        <div class="kpi__label">Average power</div>
        <div class="kpi__value" id="avg-power">—</div>
        <div class="kpi__unit">kW</div>
      </div>
      <div class="kpi">
        <div class="kpi__label">Peak power</div>
        <div class="kpi__value" id="peak-power">—</div>
        <div class="kpi__unit">kW</div>
      </div>
      <div class="kpi">
        <div class="kpi__label">Avg daily energy</div>
        <div class="kpi__value" id="daily-energy">—</div>
        <div class="kpi__unit">kWh</div>
      </div>
      <div class="kpi">
        <div class="kpi__label">Avg total energy</div>
        <div class="kpi__value" id="total-energy">—</div>
        <div class="kpi__unit">kWh</div>
      </div>
    </div>

    <div class="card">
      <div class="card__head">
        <h3>Power output &amp; load trend</h3>
        <span class="meta" id="power-meta">Averaged across active inverters</span>
      </div>
      <div class="chart-container-full">
        <canvas id="chart-power-output"></canvas>
      </div>
    </div>

    <div class="row-2-eq">
      <div class="card">
        <div class="card__head">
          <h3>Daily energy output</h3>
          <span class="meta" id="daily-energy-meta">kWh / interval</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-daily-energy"></canvas>
        </div>
      </div>
      <div class="card">
        <div class="card__head">
          <h3>Average battery SOC</h3>
          <span class="meta">Fleet state of charge</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-battery-soc"></canvas>
        </div>
      </div>
    </div>

    <div class="row-2-eq">
      <div class="card">
        <div class="card__head">
          <h3>Battery power trend</h3>
          <span class="meta">Avg charge/discharge (kW)</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-battery-power"></canvas>
        </div>
      </div>
      <div class="card">
        <div class="card__head">
          <h3>Grid power exchange</h3>
          <span class="meta">Avg import/export (kW)</span>
        </div>
        <div class="chart-container">
          <canvas id="chart-grid-power"></canvas>
        </div>
      </div>
    </div>
  </div>

  <!-- Log readings modal -->
  <div class="modal" id="log-modal" role="dialog" aria-modal="true" aria-labelledby="log-modal-title">
    <div class="modal__panel">
      <div class="modal__head">
        <h3><span id="log-modal-title">Log daily readings</span><span class="mode-pill" id="log-mode">New</span></h3>
        <button class="iconbtn" type="button" data-close aria-label="Close">✕</button>
      </div>
      <p class="modal__sub">Enter meter readings as shown on the meters the next morning. Leave a field empty if it wasn't read; the dashboard works with whatever you log.</p>
      <p class="modal__meta" id="log-meta"></p>

      <form id="log-form" class="form-grid" autocomplete="off" novalidate>
        <div class="fieldset-title">Day</div>
        <div class="field">
          <label for="f-site">Site</label>
          <select id="f-site" name="site"><option>VV</option><option>Yamin</option></select>
        </div>
        <div class="field">
          <label for="f-date">Date the water was used</label>
          <input id="f-date" name="log_date" type="date" required>
        </div>

        <div class="fieldset-title">Meter readings (cumulative)</div>
        <div class="field">
          <label for="f-bh">Borehole mechanical meter</label>
          <input id="f-bh" name="borehole_meter" type="number" step="0.01" inputmode="decimal" placeholder="e.g. 100961">
          <small id="f-bh-hint"></small>
        </div>
        <div class="field">
          <label for="f-sm">Ubuntu smart meter</label>
          <input id="f-sm" name="smart_meter" type="number" step="0.01" inputmode="decimal" placeholder="e.g. 54544.06">
          <small id="f-sm-hint"></small>
        </div>

        <div class="fieldset-title">RO plant (volumes for the day)</div>
        <div class="field">
          <label for="f-perm">Permeate to estate (booster pump), m³</label>
          <input id="f-perm" name="permeate_m3" type="number" step="0.01" inputmode="decimal">
        </div>
        <div class="field">
          <label for="f-rej">Reject water, m³</label>
          <input id="f-rej" name="reject_m3" type="number" step="0.01" inputmode="decimal">
        </div>

        <div class="fieldset-title">Sales and storage</div>
        <div class="field">
          <label for="f-sold">Units sold, m³</label>
          <input id="f-sold" name="units_sold" type="number" step="0.01" inputmode="decimal">
        </div>
        <div class="field">
          <label for="f-rw">Raw water tank level, %</label>
          <input id="f-rw" name="rw_tank_level" type="number" min="0" max="100" step="1" inputmode="numeric">
        </div>
        <div class="field">
          <label for="f-tw">Treated water tank level, %</label>
          <input id="f-tw" name="tw_tank_level" type="number" min="0" max="100" step="1" inputmode="numeric">
        </div>
        <div class="field full">
          <label for="f-notes">Notes</label>
          <textarea id="f-notes" name="notes" rows="2" placeholder="Valve changes, pump downtime, membrane cleaning…"></textarea>
        </div>
      </form>

      <div class="preview" id="log-preview">
        <div class="preview__grid" id="preview-grid"></div>
        <ul class="preview__warn" id="preview-warn"></ul>
        <ul class="changes" id="preview-changes"></ul>
      </div>

      <div class="modal__foot">
        <button class="btn btn--danger" type="button" id="delete-log-btn" hidden>Delete day</button>
        <span class="spacer"></span>
        <button class="btn btn--ghost" type="button" data-close>Cancel</button>
        <button class="btn btn--primary" type="button" id="save-log-btn">Save readings</button>
      </div>
    </div>
  </div>

  <!-- Settings modal -->
  <div class="modal" id="settings-modal" role="dialog" aria-modal="true" aria-labelledby="settings-title">
    <div class="modal__panel">
      <div class="modal__head">
        <h3 id="settings-title">Thresholds and tariff</h3>
        <button class="iconbtn" type="button" data-close aria-label="Close">✕</button>
      </div>
